Ending_Run:
    ldx     ppuBuffer0Len           ; $8BBF
    ldy     #$00                    ; $8BC2

@loop:
    lda     EndingShimmerPalette,y  ; $8BC4
    sta     ppuBuffer0,x            ; $8BC7
    inx                             ; $8BCA
    iny                             ; $8BCB
    cpy     #$08                    ; $8BCC
    bne     @loop                   ; $8BCE
