; ---------------------------------------------------------------------------
; Boss_SpawnDeathSpark_Bank5
;
; Bank 5's copy of Boss_SpawnDeathSpark_Bank4, for the Thunderbird: while
; it bursts, every other frame a spark (projectile type $0C,
; Projectile_DeathSpark_Bank5) at Y - 6 to Y + 25, X - 8 to X + 7, for 16
; frames.  Unlike bank 4's it also copies the boss's objXHi (with no carry
; from the X offset).
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Boss_SpawnDeathSpark_Bank5:
    lda     frameCounter            ; $9764  every other frame
    lsr     a                       ; $9766
    bcs     @done                   ; $9767
    jsr     Enemy_FireProjectile    ; $9769
    bcs     @done                   ; $976C  (no slot)
    lda     #$0C                    ; $976E  a spark
    sta     a:objState+7,y          ; $9770
    lda     rng+1,x                 ; $9773  Y - 6 + 0-31
    and     #$1F                    ; $9776
    adc     objY+1,x                ; $9778
    sbc     #$06                    ; $977A
    sta     a:objY+7,y              ; $977C
    lda     rng+2,x                 ; $977F  X - 8 + 0-15
    and     #$0F                    ; $9782
    sbc     #$08                    ; $9784
    adc     objX+1,x                ; $9786
    sta     a:objX+7,y              ; $9788
    lda     objXHi+1,x              ; $978B  (no carry from X)
    sta     a:objXHi+7,y            ; $978D
    lda     #$10                    ; $9790  16 frames
    sta     a:objXVelocity+7,y      ; $9792

@done:
    rts                             ; $9795

; ---------------------------------------------------------------------------
; DarkLink_Init
;
; Spawn routine of the Dark Link trigger ($23, in the last room): it moves
; itself to enemy slot 0, whatever is there (the trigger, alone in its
; room, spawns in slot 5), as type $23 with 8 hit points, at the trigger's
; place, and frees its own slot.  Dark Link's phase and scratch
; (objFacing+2 to +5) start at 0; extraSpriteAttrs = 2.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_Init:
    lda     #$23                    ; $9796  slot 0: type $23,
    sta     enemyType               ; $9798
    lda     #$08                    ; $979A  8 hit points,
    sta     enemyHp                 ; $979C
    lda     objX+1,x                ; $979E  at the trigger's place
    sta     objX+1                  ; $97A0
    lda     objY+1,x                ; $97A2
    sta     objY+1                  ; $97A4
    lda     objXHi+1,x              ; $97A6
    sta     objXHi+1                ; $97A8
    lda     #$02                    ; $97AA
    sta     extraSpriteAttrs        ; $97AC
    lsr     a                       ; $97AF
    sta     objYHi+1                ; $97B0
    sta     enemyActive             ; $97B2  active
    lsr     a                       ; $97B4
    sta     enemyActive,x           ; $97B5  the trigger's slot freed
    sta     objFacing+2             ; $97B7  scratch and phase 0
    sta     objFacing+3             ; $97B9
    sta     objFacing+4             ; $97BB
    sta     objFacing+5             ; $97BD
    lda     enemySramIndex,x        ; $97BF
    sta     enemySramIndex          ; $97C1
    rts                             ; $97C3
; (unreferenced: $97C4-$97C5, 2 bytes)
    .byte   $03, $FD                                                        ; $97C4

; ---------------------------------------------------------------------------
; DarkLink_Ai
;
; Dark Link ($23, enemy slot 0, drawn and moved as object 1), by its phase
; in objFacing+4: 0 DarkLink_WaitForLink, 1 DarkLink_Appear, 2
; DarkLink_Separate, 3 DarkLink_Fight, 4 DarkLink_Defeated, 5
; DarkLink_WalkLinkToCenter, 6 DarkLink_ShowTriforce, 7
; DarkLink_StartEnding.  Every phase first queues the room's flashing
; color of the Triforce (Triforce_FlashPalette).
;
; Its scratch: objFacing+2 the way it backs off or approaches (0 right, 1
; left), objFacing+3 1 while in the air, objFacing+5 its walking frame;
; timerFast+3 its phase and attack timer, timerFast+4 the fight's start,
; timerFast+5 backing off or approaching, timerFast+8 (enemy slot 5's)
; invulnerability after a hit, and timerFast+TIMER_BOSS knockback or
; death.
;
; In:      x = enemy index (0)
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_Ai:
    jsr     Triforce_FlashPalette   ; $97C6
    lda     objFacing+4             ; $97C9
    jsr     JumpTable               ; $97CB
; (inline jump table)
    .word   DarkLink_WaitForLink    ; $97CE
    .word   DarkLink_Appear         ; $97D0
    .word   DarkLink_Separate       ; $97D2
    .word   DarkLink_Fight          ; $97D4
    .word   DarkLink_Defeated       ; $97D6
    .word   DarkLink_WalkLinkToCenter ; $97D8
    .word   DarkLink_ShowTriforce   ; $97DA
    .word   DarkLink_StartEnding    ; $97DC

; ---------------------------------------------------------------------------
; DarkLink_WaitForLink
;
; Phase 0: drawn as type $23 (OldMan_Draw).  When Link's screen
; reaches page 1 of the room, the scroll freezes and Link stops; once he
; is on the floor he is set at Y $A0 facing right, the game freezes, and
; phase 1 starts with timerFast+3 = 255.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_WaitForLink:
    inc     enemyAiState            ; $97DE  animation count
    jsr     Enemy_Draw              ; $97E0
    lda     scrollXHi               ; $97E3  Link's screen at page 1?
    beq     DarkLink_WaitForLink_Done ; $97E6
    inc     scrollFrozen            ; $97E8  scroll frozen,
    lda     #$00                    ; $97EB  Link stops
    sta     objXVelocity            ; $97ED
    lda     objCollision            ; $97EF  on the floor?
    and     #$04                    ; $97F1
    beq     DarkLink_WaitForLink_Done ; $97F3
    lda     #$A0                    ; $97F5  at Y $A0,
    sta     objY                    ; $97F7
    lda     #$03                    ; $97F9  state 3,
    sta     objState                ; $97FB
    lsr     a                       ; $97FD  facing right;
    sta     linkWalkDir             ; $97FE
    asl     a                       ; $9800  Dark Link's sprites left
    sta     darkLinkWalkDir         ; $9801
    lda     #$FF                    ; $9803

DarkLink_Freeze:
    inc     gameFrozen              ; $9805  freeze the game

DarkLink_SetTimer:
    sta     timerFast+3             ; $9807

DarkLink_NextPhase:
    inc     objFacing+4             ; $980A

DarkLink_WaitForLink_Done:
    rts                             ; $980C

; ---------------------------------------------------------------------------
; DarkLink_Appear
;
; Phase 1, counting timerFast+3 down from 255: 63 frames drawn as before,
; 112 frames flickering (every other frame), 80 not drawn.  Then the
; screen flashes (spellFlash $C0) with sound 4 and the backdrop $14, and
; Dark Link is put on Link; phase 2 with the timer at 255.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_Appear:
    lda     timerFast+3             ; $980D  time up?
    bne     @wait                   ; $9810
    lda     #$C0                    ; $9812  flash,
    sta     spellFlash              ; $9814
    lda     #$04                    ; $9817  sound,
    sta     sfxRequest              ; $9819
    lda     #$14                    ; $981B  backdrop
    sta     backdropColor           ; $981D
    lda     objX                    ; $9820  Dark Link on Link
    sta     objX+1                  ; $9822
    lda     objY                    ; $9824
    sta     objY+1                  ; $9826
    lda     #$FF                    ; $9828
    bne     DarkLink_SetTimer       ; $982A

@wait:
    cmp     #$50                    ; $982C  below $50: not drawn
    bcc     DarkLink_WaitForLink_Done ; $982E
    cmp     #$C0                    ; $9830  $C0 on: animated
    bcs     @animate                ; $9832
    lsr     a                       ; $9834  else every other frame
    bcc     DarkLink_WaitForLink_Done ; $9835
    bcs     @draw                   ; $9837

@animate:
    inc     enemyAiState,x          ; $9839

@draw:
    jmp     Enemy_Draw              ; $983B

; ---------------------------------------------------------------------------
; DarkLink_Separate
;
; Phase 2: Dark Link, in pose $0A, steps out of Link.  When the flash ends
; (spellFlash $81), the room's palette string $0D is written, the music
; stops and sound 4 plays.  For 127 frames it stays on him; then it jumps
; right (4 pixels per frame up, about 1.2 across) and falls.  When it lands
; at Y $A0, phase 3 starts, the fight 112 frames later (timerFast+4).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_Separate:
    lda     spellFlash              ; $983E  flash ending?
    cmp     #$81                    ; $9841
    bne     @checkTimer             ; $9843
    lda     #$0D                    ; $9845  palette string $0D,
    sta     ppuStringSelect         ; $9847
    lda     #$80                    ; $984A  music off,
    sta     musicRequest            ; $984C
    lda     #$04                    ; $984E  sound
    sta     sfxRequest              ; $9850

@checkTimer:
    lda     timerFast+3             ; $9852  waiting (timer above $80)
    cmp     #$80                    ; $9855
    bcc     @move                   ; $9857
    bne     DarkLink_WaitForLink_Done ; $9859
    lda     #$FC                    ; $985B  at $80: jump out
    sta     objYVelocity+1          ; $985D
    lda     #$13                    ; $9860
    sta     objXVelocity+1          ; $9862

@move:
    jsr     DarkLink_Move           ; $9864
    lda     objY+1                  ; $9867  landed?
    cmp     #$A0                    ; $9869
    bcc     @draw                   ; $986B
    inc     objFacing+4             ; $986D  phase 3
    lda     #$70                    ; $986F
    sta     timerFast+4             ; $9871

@draw:
    lda     #$0A                    ; $9874
    sta     objState+1              ; $9876
    jmp     DarkLink_Draw           ; $9878

; ---------------------------------------------------------------------------
; DarkLink_Fight
;
; Phase 3.  For 112 frames (timerFast+4) it crouches (pose 6); then the
; fight music ($40) starts and the game unfreezes.  It shows its hit
; points in the boss bar, a unit each.
;
; Knocked back (timerFast+TIMER_BOSS below $80, 24 frames) or dying ($FF
; down), it is in pose $0A, moved with gravity but not landed; dying, it
; sounds every 16 frames and sinks through the floor.  At Y $F0 the screen
; flashes ($B0) with sound 4, the backdrop goes black, the music stops and
; phase 4 starts (timerFast+3 = 64).
;
; Otherwise: DarkLink_ReactToLink, DarkLink_UpdateXVelocity,
; DarkLink_UpdateJump, DarkLink_UpdateAttack, DarkLink_Draw,
; DarkLink_CheckSword, and body contact, which hurts Link.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_Fight:
    ldy     timerFast+4             ; $987B  starting?
    beq     @started                ; $987E
    dey                             ; $9880  the last frame: music
    bne     @crouch                 ; $9881
    lda     #$40                    ; $9883
    sta     musicRequest            ; $9885

@crouch:
    lda     #$06                    ; $9887
    sta     objState+1              ; $9889
    jmp     DarkLink_Draw           ; $988B

@started:
    lda     musicPlaying            ; $988E  (music again if none)
    bne     @unfreeze               ; $9891
; (code below not executed in the test movies)
    lda     #$40                    ; $9893
    sta     musicRequest            ; $9895
; (end of code not executed in the test movies)

@unfreeze:
    sty     gameFrozen              ; $9897  (y = 0)
    lda     #$01                    ; $9899  hit point bar, 1 per unit
    jsr     Boss_DrawHpBar_Bank5    ; $989B
    lda     timerFast+TIMER_BOSS    ; $989E  knocked back or dying?
    beq     @fight                  ; $98A1
    bpl     @knockedBack            ; $98A3
    and     #$0F                    ; $98A5  dying: a sound every 16
    bne     @knockedBack            ; $98A7  frames
    lda     #$01                    ; $98A9
    sta     dmcRequest              ; $98AB

@knockedBack:
    lda     #$0A                    ; $98AD  pose $0A, moved, not landed
    sta     objState+1              ; $98AF
    jsr     DarkLink_Move           ; $98B1
    lda     objY+1                  ; $98B4  sunk below the screen?
    cmp     #$F0                    ; $98B6
    bcc     @draw                   ; $98B8
    lda     #$B0                    ; $98BA  flash,
    sta     spellFlash              ; $98BC
    lda     #$04                    ; $98BF  sound,
    sta     sfxRequest              ; $98C1
    lda     #$0F                    ; $98C3  black backdrop,
    sta     backdropColor           ; $98C5
    lda     #$80                    ; $98C8  music off;
    sta     musicRequest            ; $98CA
    lsr     a                       ; $98CC  phase 4, 64 frames
    jsr     DarkLink_SetTimer       ; $98CD

@draw:
    jmp     DarkLink_Draw           ; $98D0

@fight:
    jsr     DarkLink_ReactToLink    ; $98D3
    jsr     DarkLink_UpdateXVelocity ; $98D6
    jsr     DarkLink_UpdateJump     ; $98D9
    jsr     DarkLink_UpdateAttack   ; $98DC
    jsr     DarkLink_Draw           ; $98DF
    jsr     DarkLink_CheckSword     ; $98E2
    jsr     Enemy_CheckLinkContact  ; $98E5
    jmp     Enemy_HurtLinkOnContact ; $98E8

; ---------------------------------------------------------------------------
; DarkLink_ReactToLink
;
; On the floor, by its distance from Link across ((|dx| + 3) / 16):
; - 0-1 (within about 28 pixels): when Link presses B it takes his
;   stance (darkLinkStanding = linkStanding), so its shield meets his
;   stroke, and 1 time in 8 it jumps away (DarkLink_GetSide).  Otherwise
;   DarkLink_MaybeTurn: back off or attack.
; - 2-5 (up to about 92): DarkLink_TurnSometimes, approach.
; - 6 or more: stand up, and wait.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_ReactToLink:
    lda     objX+1                  ; $98EB  distance from Link
    sbc     objX                    ; $98ED  (the carry isn't set up)
    bpl     @abs                    ; $98EF
    eor     #$FF                    ; $98F1

@abs:
    adc     #$03                    ; $98F3
    lsr     a                       ; $98F5
    lsr     a                       ; $98F6
    lsr     a                       ; $98F7
    lsr     a                       ; $98F8
    cmp     #$06                    ; $98F9
    bcs     @far                    ; $98FB
    jsr     JumpTable               ; $98FD
; (inline jump table)
    .word   @close                  ; $9900
    .word   @close                  ; $9902
    .word   DarkLink_TurnSometimes  ; $9904
    .word   DarkLink_TurnSometimes  ; $9906
    .word   DarkLink_TurnSometimes  ; $9908
    .word   DarkLink_TurnSometimes  ; $990A
; (code below not executed in the test movies)

@far:
    lda     #$01                    ; $990C  far: stand
    sta     darkLinkStanding        ; $990E
    rts                             ; $9910
; (end of code not executed in the test movies)

@close:
    lda     objFacing+3             ; $9911  in the air: nothing
    bne     DarkLink_ReactToLink_Done ; $9913
    lda     joypadPressed           ; $9915  Link pressed B?
    and     #$40                    ; $9917
    beq     DarkLink_MaybeTurn      ; $9919
    lda     linkStanding            ; $991B  take his stance
    sta     darkLinkStanding        ; $991D
    lda     rng+1                   ; $991F  1 time in 8,
    and     #$07                    ; $9922
    bne     DarkLink_MaybeTurn      ; $9924
; (code below not executed in the test movies)
    sta     objYFrac+1              ; $9926  jump away, the attack off
    sta     enemyAiDir              ; $9929
; (end of code not executed in the test movies)

; Jump: 1.5 pixels per frame toward the middle of the screen, or 1 time in
; 4 (rng+2 bits 1-0 zero) straight up; 4 pixels per frame up, standing.
DarkLink_GetSide:
    ldy     #$00                    ; $992C  right if in the left half,
    lda     drawScreenX+1           ; $992E
    adc     #$0C                    ; $9930
    bpl     @checkUp                ; $9932
; (code below not executed in the test movies)
    iny                             ; $9934  else left
; (end of code not executed in the test movies)

@checkUp:
    lda     rng+2                   ; $9935  1 in 4: straight up
    and     #$03                    ; $9938
    bne     @setSpeed               ; $993A
; (code below not executed in the test movies)
    iny                             ; $993C
    iny                             ; $993D
; (end of code not executed in the test movies)

@setSpeed:
    lda     DarkLinkReactSpeeds,y   ; $993E
    sta     objXVelocity+1          ; $9941
    lda     #$FC                    ; $9943
    sta     objYVelocity+1          ; $9945
    lda     #$01                    ; $9948  in the air, standing
    sta     objFacing+3             ; $994A
    sta     darkLinkStanding        ; $994C

DarkLink_ReactToLink_Done:
    rts                             ; $994E

; Close to Link: 1 frame in 4 (rng+3 bits 1-0 zero) back off for 16
; frames.  Else, unless it is already attacking (attack step 1 or 2) or
; is above him, attack: at the height his shield isn't (its stance the
; opposite of his), standing still, with a sound; the wind-up lasts 16
; frames.
DarkLink_MaybeTurn:
    lda     rng+3                   ; $994F  1 in 4:
    and     #$03                    ; $9952
    bne     @attack                 ; $9954
    jsr     Enemy_FaceLink          ; $9956  back off, away from him,
    tya                             ; $9959
    eor     #$01                    ; $995A
    sta     objFacing+2             ; $995C
    lda     #$10                    ; $995E  for 16 frames
    sta     timerFast+5             ; $9960
    rts                             ; $9963

@attack:
    ldy     enemyAiDir              ; $9964  attacking already?
    dey                             ; $9967
    cpy     #$02                    ; $9968
    bcc     @done                   ; $996A
    lda     objY+1                  ; $996C  above Link?
    cmp     objY                    ; $996E
    bcc     @done                   ; $9970
    lda     linkStanding            ; $9972  attack where his shield isn't
    eor     #$01                    ; $9974
    sta     darkLinkStanding        ; $9976
    lda     #$01                    ; $9978  step 1,
    sta     enemyAiDir              ; $997A
    lsr     a                       ; $997D  standing still,
    sta     objXVelocity+1          ; $997E
    lda     #$20                    ; $9980  sound,
    sta     sfxRequest+1            ; $9982
    lsr     a                       ; $9984  16 frames
    sta     timerFast+3             ; $9985

@done:
    rts                             ; $9988

; Farther from Link: in 3 of every 4 64-frame periods (frameCounter bits
; 7-6 not zero), walk toward him (for 2 frames, renewed each frame).
DarkLink_TurnSometimes:
    lda     objFacing+3             ; $9989  in the air: nothing
    bne     @done                   ; $998B
    lda     frameCounter            ; $998D
    and     #$C0                    ; $998F
    beq     @done                   ; $9991
    jsr     Enemy_FaceLink          ; $9993  toward him
    sty     objFacing+2             ; $9996
    lda     #$02                    ; $9998
    sta     timerFast+5             ; $999A

@done:
    rts                             ; $999D

; Jumps: right, left (1.5 pixels per frame), straight up (twice).
DarkLinkReactSpeeds:
    .byte   $18, $E8, $00, $00                                              ; $999E

; Backing off or approaching: 1.25 pixels per frame by objFacing+2.
DarkLinkSpeeds:
    .byte   $14, $EC                                                        ; $99A2

; ---------------------------------------------------------------------------
; DarkLink_UpdateXVelocity
;
; While it backs off or approaches (timerFast+5), its X velocity is 1.25
; pixels per frame that way; otherwise, on the floor, 0.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_UpdateXVelocity:
    lda     timerFast+5             ; $99A4  backing off or approaching?
    beq     @stop                   ; $99A7
    ldy     objFacing+2             ; $99A9
    lda     DarkLinkSpeeds,y        ; $99AB
    sta     objXVelocity+1          ; $99AE
    rts                             ; $99B0

@stop:
    lda     objFacing+3             ; $99B1  on the floor: stand
    bne     @done                   ; $99B3
    sta     objXVelocity+1          ; $99B5

@done:
    rts                             ; $99B7

; ---------------------------------------------------------------------------
; DarkLink_UpdateJump
;
; Move it (DarkLink_Move); at Y $A0 or below it stands on the floor
; (DarkLink_Animate).  In the air it takes Link's stance, in pose 6 going
; up and 2 coming down.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_UpdateJump:
    jsr     DarkLink_Move           ; $99B8
    lda     objY+1                  ; $99BB  on the floor?
    cmp     #$A0                    ; $99BD
    bcc     @inAir                  ; $99BF
    jsr     Enemy_Land              ; $99C1
    sta     objFacing+3             ; $99C4  (a = 0) not in the air
    lda     #$A0                    ; $99C6
    sta     objY+1                  ; $99C8
    bne     DarkLink_Animate        ; $99CA

@inAir:
    lda     linkStanding            ; $99CC  Link's stance
    sta     darkLinkStanding        ; $99CE
    lda     #$06                    ; $99D0  pose 6 up, 2 down
    ldy     objYVelocity+1          ; $99D2
    bmi     @setPose                ; $99D5
    lda     #$02                    ; $99D7

@setPose:
    sta     objState+1              ; $99D9
    rts                             ; $99DB

; Walking poses by objFacing+5: forward, then (+3) backward.
DarkLinkWalkPoses:
    .byte   $00, $01, $02, $02, $01, $00                                    ; $99DC

; On the floor: walking (frames every 4 frames, backward when it moves
; away from the way it faces), or standing still, pose 3 standing or 6
; crouching.
DarkLink_Animate:
    lda     objXVelocity+1          ; $99E2  moving?
    beq     @still                  ; $99E4
    ldy     objFacing+5             ; $99E6  next frame every 4 frames,
    lda     frameCounter            ; $99E8  0-2
    and     #$03                    ; $99EA
    bne     @checkBackward          ; $99EC
    inc     objFacing+5             ; $99EE
    cpy     #$02                    ; $99F0
    bne     @checkBackward          ; $99F2
    sta     objFacing+5             ; $99F4

@checkBackward:
    lda     objFacing+1             ; $99F6  moving the way it faces?
    cmp     darkLinkWalkDir         ; $99F8
    beq     @setWalkPose            ; $99FA
    iny                             ; $99FC  no: backward
    iny                             ; $99FD
    iny                             ; $99FE

@setWalkPose:
    lda     DarkLinkWalkPoses,y     ; $99FF
    sta     objState+1              ; $9A02
    rts                             ; $9A04

@still:
    lda     #$03                    ; $9A05  standing, 3,
    ldy     darkLinkStanding        ; $9A07
    bne     @setStillPose           ; $9A09
    asl     a                       ; $9A0B  crouching, 6

@setStillPose:
    sta     objState+1              ; $9A0C
    rts                             ; $9A0E

; ---------------------------------------------------------------------------
; DarkLink_Move
;
; Face Link (its sprites, darkLinkWalkDir), and its objFacing the way it
; moves.  At the edge of the screen: on the floor it jumps toward the
; middle (DarkLink_GetSide, with rng+2 forced so it doesn't jump straight
; up), and it doesn't move further toward the edge.  Then move it with
; gravity ($3C/256 pixel per frame per frame, up to 4 pixels per frame).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_Move:
    jsr     Enemy_FaceLink          ; $9A0F  its sprites face Link
    lda     objFacing+1             ; $9A12
    sta     darkLinkWalkDir         ; $9A14
    ldy     #$01                    ; $9A16  its facing: the way it moves
    lda     objXVelocity+1          ; $9A18
    bpl     @setFacing              ; $9A1A
    iny                             ; $9A1C

@setFacing:
    sty     objFacing+1             ; $9A1D
    lda     drawOffscreen+1         ; $9A1F  at an edge of the screen?
    and     #$09                    ; $9A21
    beq     @moveX                  ; $9A23
    ldy     objFacing+3             ; $9A25  on the floor: jump back
    bne     @checkEdge              ; $9A27
    pha                             ; $9A29
    lda     #$03                    ; $9A2A  (not straight up)
    sta     rng+2                   ; $9A2C
    jsr     DarkLink_GetSide        ; $9A2F
    pla                             ; $9A32

@checkEdge:
    lsr     a                       ; $9A33  moving toward that edge:
    lsr     a                       ; $9A34  don't
    lsr     a                       ; $9A35
    tay                             ; $9A36
    iny                             ; $9A37
    cpy     objFacing+1             ; $9A38
    beq     @moveY                  ; $9A3A

@moveX:
    jsr     Enemy_MoveX             ; $9A3C

@moveY:
    lda     #$3C                    ; $9A3F  gravity $3C/256,
    sta     temp0                   ; $9A41
    lda     #$04                    ; $9A43  up to 4 px/frame
    sta     temp2                   ; $9A45
; Attack poses by step 1-3: standing 4, 5, 4, then (+3) crouching 6, 7, 6
; (entry 0 is the jmp's high byte).
DarkLinkAttackPoses := * + 2
    jmp     Enemy_MoveYWithGravity  ; $9A47
    .byte   $04, $05, $04, $06, $07, $06                                    ; $9A4A

; ---------------------------------------------------------------------------
; DarkLink_UpdateAttack
;
; The attack, by step (enemyAiDir): 1, the wind-up, for the 16 frames
; DarkLink_MaybeTurn set; 2, the thrust, 8 frames; 3, 8 frames; then done.
; Its pose by step and stance (DarkLinkAttackPoses).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_UpdateAttack:
    ldy     enemyAiDir              ; $9A50  attacking?
    beq     @done                   ; $9A53
    lda     timerFast+3             ; $9A55  step over?
    bne     @setPose                ; $9A58
    inc     enemyAiDir              ; $9A5A  next step
    cpy     #$03                    ; $9A5D  after 3: done
    bne     @nextStep               ; $9A5F
; (code below not executed in the test movies)
    sta     enemyAiDir              ; $9A61
    rts                             ; $9A64
; (end of code not executed in the test movies)

@nextStep:
    lda     #$08                    ; $9A65  8 frames
    sta     timerFast+3             ; $9A67

@setPose:
    lda     darkLinkStanding        ; $9A6A  pose by step and stance
    bne     @standing               ; $9A6C
    iny                             ; $9A6E
    iny                             ; $9A6F
    iny                             ; $9A70

@standing:
    lda     DarkLinkAttackPoses,y   ; $9A71
    sta     objState+1              ; $9A74

@done:
    rts                             ; $9A76

; ---------------------------------------------------------------------------
; DarkLink_Draw
;
; Draw Dark Link with Link's own drawing code (Link_DrawBody, for object
; 1, swordOwner 1): its body and sword in its pose (objState+1), facing
; darkLinkWalkDir, at oamBuffer offset $50.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_Draw:
    ldy     #$01                    ; $9A77
    sty     swordOwner              ; $9A79
    lda     #$50                    ; $9A7B
    sta     objOamOffset+1          ; $9A7D
    jsr     Link_DrawBody           ; $9A7F
    ldx     currentObject           ; $9A82

DarkLink_Draw_Done:
    rts                             ; $9A84
; Its shield's X offset by darkLinkWalkDir (1 right: +16, 2 left: -1;
; entry 0 is the rts).
DarkLinkSwordXOffsets := DarkLink_Draw_Done
    .byte   $10, $FF                                                        ; $9A85

; Its shield's Y offset by darkLinkStanding: crouching +17, standing +4.
DarkLinkSwordYOffsets:
    .byte   $11, $04                                                        ; $9A87

; Its sword's box X offset: -8 when the sword is right of Dark Link's X
; (it faces right), else +2.
DarkLinkSwordXOffsets2:
    .byte   $F8, $02                                                        ; $9A89

; Knockback after a hit, away from Link (by Enemy_FaceLink's y).
DarkLinkKnockBackSpeeds:
    .byte   $F6, $0A                                                        ; $9A8B

; ---------------------------------------------------------------------------
; DarkLink_CheckSword
;
; The sword tests, skipped while either of them is in the air or Dark Link
; is invulnerable (timerFast+8):
; 1. Link's sword (Sword_GetHitbox) against its shield, a box 6 wide and
;    9 high in front of it at its stance's height: a clink.  Both are
;    knocked back (Enemy_KnockBack), it at Link's X velocity reversed.
; 2. Else against its body (29 high): a hit.  Its attack is cut off and it
;    loses 1 hit point, whatever Link's attack level.  Not the last: it is
;    invulnerable for 56 frames and knocked back for 24
;    (timerFast+TIMER_BOSS), hopping 3 pixels per frame up and 0.625 away
;    from Link, with a sound.  The last: the timer is $FF, its death.
; 3. Else its sword (swordX+1, swordY+1, a box 14 by 2) against Link's
;    shield: a clink as in 1; else against Link, who is hurt
;    (Link_HurtByEnemy).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_CheckSword:
    lda     objFacing+3             ; $9A8D  either in the air, or
    ora     linkJumpState           ; $9A8F  invulnerable: no tests
    ora     timerFast+8             ; $9A92
    bne     @done                   ; $9A95
    jsr     Sword_GetHitbox         ; $9A97  Link's sword (box A)
    ldy     darkLinkWalkDir         ; $9A9A  against its shield (box B)
    lda     drawScreenX+1           ; $9A9C
    adc     #$08                    ; $9A9E
    adc     DarkLinkSwordXOffsets,y ; $9AA0
    sta     temp4                   ; $9AA3
    lda     #$06                    ; $9AA5
    sta     temp6                   ; $9AA7
    ldy     darkLinkStanding        ; $9AA9
    lda     objY+1                  ; $9AAB
    adc     DarkLinkSwordYOffsets,y ; $9AAD
    sta     temp5                   ; $9AB0
    lda     #$09                    ; $9AB2
    sta     temp7                   ; $9AB4
    jsr     Hitbox_Overlap          ; $9AB6
    bcs     @clink                  ; $9AB9
    jsr     Enemy_GetHitbox         ; $9ABB  against its body,
    ldy     darkLinkStanding        ; $9ABE  29 high
    lda     objY+1                  ; $9AC0
    sta     temp5                   ; $9AC2
    lda     #$1D                    ; $9AC4
    sta     temp7                   ; $9AC6
    jsr     Hitbox_Overlap          ; $9AC8
    bcc     @checkItsSword          ; $9ACB
    ldy     #$00                    ; $9ACD  hit: attack off,
    sty     enemyAiDir              ; $9ACF
    dey                             ; $9AD2
    dec     enemyHp                 ; $9AD3  a hit point
    beq     @setTimer               ; $9AD5  (the last: death, $FF)
    lda     #$38                    ; $9AD7  invulnerable 56 frames,
    sta     timerFast+8             ; $9AD9
    ldy     #$18                    ; $9ADC  knocked back 24

@setTimer:
    sty     timerFast+TIMER_BOSS    ; $9ADE
    jsr     Enemy_FaceLink          ; $9AE1  away from Link,
    lda     DarkLinkKnockBackSpeeds,y ; $9AE4
    sta     objXVelocity+1          ; $9AE7
    lda     #$FD                    ; $9AE9  hopping
    sta     objYVelocity+1          ; $9AEB
    lda     #$01                    ; $9AEE  sound
    sta     dmcRequest              ; $9AF0
    sta     objFacing+3             ; $9AF2  in the air

@done:
    rts                             ; $9AF4

@clink:
    lda     #$00                    ; $9AF5  both knocked back,
    sta     temp11                  ; $9AF7
    jsr     Enemy_KnockBack         ; $9AF9
    lda     objXVelocity            ; $9AFC  it at Link's velocity
    eor     #$FF                    ; $9AFE  reversed,
    sta     objXVelocity+1          ; $9B00
    lda     #$02                    ; $9B02  clink
    sta     sfxRequest              ; $9B04

@done2:
    rts                             ; $9B06

@checkItsSword:
    jsr     Link_GetShieldHitbox    ; $9B07  Link's shield (box A)
    ldy     #$00                    ; $9B0A  against its sword (box B)
    lda     swordX+1                ; $9B0C
    pha                             ; $9B0F
    cmp     drawScreenX+1           ; $9B10
    bcs     @swordBox               ; $9B12
    iny                             ; $9B14

@swordBox:
    pla                             ; $9B15
    adc     DarkLinkSwordXOffsets2,y ; $9B16
    sta     temp4                   ; $9B19
    lda     #$0E                    ; $9B1B
    sta     temp6                   ; $9B1D
    lda     swordY+1                ; $9B1F
    adc     #$03                    ; $9B22
    sta     temp5                   ; $9B24
    lda     #$02                    ; $9B26
    sta     temp7                   ; $9B28
    jsr     Hitbox_Overlap          ; $9B2A
    bcs     @clink                  ; $9B2D
    jsr     Link_GetHitbox          ; $9B2F  against Link
    jsr     Hitbox_Overlap          ; $9B32
    bcc     @done2                  ; $9B35
; (code below not executed in the test movies)
    jmp     Link_HurtByEnemy        ; $9B37
; (end of code not executed in the test movies)

; ---------------------------------------------------------------------------
; DarkLink_Defeated
;
; Phase 4: when the flash ends, the room's palette string $0E is written.
; When Link is on the floor and the 64 frames are up, the game freezes and
; phase 5 starts (timerFast+3 = 128).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_Defeated:
    lda     spellFlash              ; $9B3A  flash ending?
    cmp     #$81                    ; $9B3D
    bne     @checkLink              ; $9B3F
    lda     #$0E                    ; $9B41  palette string $0E
    sta     ppuStringSelect         ; $9B43

@checkLink:
    lda     linkJumpState           ; $9B46  Link landed, time up?
    ora     timerFast+3             ; $9B49
    bne     DarkLink_WalkLinkToCenter_Done ; $9B4C
    lda     #$80                    ; $9B4E
    jmp     DarkLink_Freeze         ; $9B50

; ---------------------------------------------------------------------------
; DarkLink_WalkLinkToCenter
;
; Phase 5: Link in state 3; after 128 frames he walks a pixel per frame to
; X $160 (objX + $0B = $6C on page 1), facing right.  Then Dark Link
; (object 1, where the old man will stand) goes to ($17C, $B0) and phase 6
; starts (timerSlow+4 = $0D).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_WalkLinkToCenter:
    lda     #$03                    ; $9B53  Link: state 3
    sta     objState                ; $9B55
    ldy     timerFast+3             ; $9B57  waiting?
    bne     DarkLink_WalkLinkToCenter_Done ; $9B5A
    lsr     a                       ; $9B5C  facing right, both on page 1
    sta     linkWalkDir             ; $9B5D
    sta     objXHi                  ; $9B5F
    sta     objXHi+1                ; $9B61
    lda     objX                    ; $9B63  at the middle?
    adc     #$0B                    ; $9B65
    cmp     #$6C                    ; $9B67
    beq     DarkLink_StartWalk      ; $9B69
    dec     objX                    ; $9B6B  else a pixel toward it
    bcs     DarkLink_WalkLinkToCenter_Done ; $9B6D
; (code below not executed in the test movies)
    inc     objX                    ; $9B6F
    inc     objX                    ; $9B71
; (end of code not executed in the test movies)

DarkLink_WalkLinkToCenter_Done:
    rts                             ; $9B73

DarkLink_StartTriforce:
    lda     #$C0                    ; $9B74  flash,
    sta     spellFlash              ; $9B76
    lda     #$20                    ; $9B79  music $20,
    sta     musicRequest            ; $9B7B
    lda     #$15                    ; $9B7D  phase 7, timerSlow+4 = $15
    bne     DarkLink_PlaceAtCenter  ; $9B7F

DarkLink_StartWalk:
    lda     #$0D                    ; $9B81  phase 6, timerSlow+4 = $0D

DarkLink_PlaceAtCenter:
    sta     timerSlow+4             ; $9B83
    lda     #$7C                    ; $9B86  object 1 at ($17C, $B0)
    sta     objX+1                  ; $9B88
    lda     #$B0                    ; $9B8A
    sta     objY+1                  ; $9B8C
    jmp     DarkLink_NextPhase      ; $9B8E

; ---------------------------------------------------------------------------
; DarkLink_ShowTriforce
;
; Phase 6, by timerSlow+4 from $0D (a step every 21 frames): from 8 the
; old man stands beside Link with the Triforce above him (OldMan_Draw
; through Enemy_Draw), flickering until 5; at 2 the screen flashes, music
; $20 plays and phase 7 starts (DarkLink_StartTriforce).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_ShowTriforce:
    lda     timerSlow+4             ; $9B91
    cmp     #$02                    ; $9B94  at 2: phase 7
    beq     DarkLink_StartTriforce  ; $9B96
    cmp     #$09                    ; $9B98  9 or more: nothing yet
    bcs     DarkLink_WalkLinkToCenter_Done ; $9B9A
    cmp     #$06                    ; $9B9C  6-8: every other frame
    bcc     @draw                   ; $9B9E
    lda     frameCounter            ; $9BA0
    lsr     a                       ; $9BA2
    bcc     DarkLink_WalkLinkToCenter_Done ; $9BA3

@draw:
    jmp     Enemy_Draw              ; $9BA5

; ---------------------------------------------------------------------------
; DarkLink_StartEnding
;
; Phase 7: Link faces left, holding the Triforce up (state $0B), the old
; man beside him, until timerSlow+4 runs out from $15 (about 440 frames);
; then the ending starts (gameState 3) with rendering off.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
DarkLink_StartEnding:
    lda     #$02                    ; $9BA8  Link faces left,
    sta     linkWalkDir             ; $9BAA
    ldy     timerSlow+4             ; $9BAC  time up?
    beq     @ending                 ; $9BAF
    lda     #$0B                    ; $9BB1  state $0B
    sta     objState                ; $9BB3
    inc     enemyAiState            ; $9BB5
    jmp     Enemy_Draw              ; $9BB7

@ending:
    lda     #$03                    ; $9BBA  the ending
    sta     gameState               ; $9BBC
    lda     #$00                    ; $9BBF
    sta     PPUMASK                 ; $9BC1
    inc     renderingOff            ; $9BC4
    rts                             ; $9BC7

; ---------------------------------------------------------------------------
; Projectile_Fireball_Bank5
;
; Projectile types 4 and 8 (the Thunderbird's fireballs): fall with gravity
; (1/16 pixel per frame per frame) from the speeds they were launched with,
; and burst ($F4) when they hit the background.
;
; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_Fireball_Bank5:
    jsr     Projectile_HitsBg       ; $9BC8  hit the background?
    bcc     Projectile_Fall_Bank5   ; $9BCB  no: fall
    lda     #$F4                    ; $9BCD  yes: burst
    sta     objState+7,x            ; $9BCF
    rts                             ; $9BD1

; ---------------------------------------------------------------------------
; Projectile_Rock_Bank5
;
; Projectile type 5 (a Fokka's thrown sword): flies level the way it was
; thrown; once deflected (moving against its
; facing) it falls, gaining 2/16 pixel per frame each frame.  Link's
; shield stops it only with the reflect spell (flags $86).
;
; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_Rock_Bank5:
    ldy     #$02                    ; $9BD2  moving its facing's way?
    lda     objXVelocity+7,x        ; $9BD4
    bmi     @checkFacing            ; $9BD6
    dey                             ; $9BD8

@checkFacing:
    tya                             ; $9BD9
    cmp     objFacing+7,x           ; $9BDA
    bne     Projectile_FallFast_Bank5 ; $9BDC  no: deflected, fall
    jmp     Projectile_Straight_Bank5 ; $9BDE  yes: level

; ---------------------------------------------------------------------------
; Projectile_RollingFlame_Bank5
;
; Projectile type 7 (the Fokkeru's fireball): flies in an arc, falling
; with gravity (1/16 pixel per frame per frame), until it meets the
; background.  Each frame it touches it, there is a sound and it is set on
; the tile row.  The first time (projectileSpeed 0), it stops and hops a
; little (1 pixel per frame up), and then either (3 times in 4) burns in
; place for 48 frames, or rolls toward Link (by its screen X against
; his) at 1 pixel per frame, slowing by 1/16 every 8 frames, for 255
; frames.  It falls off ledges, and goes on off the side of the screen.
;
; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_RollingFlame_Bank5:
    jsr     Projectile_HitsBgAnyHeight ; $9BE1  on the background?
    bcc     Projectile_Fall_Bank5   ; $9BE4  no: fall
    lda     sfxRequest+1            ; $9BE6  sound
    ora     #$40                    ; $9BE8
    sta     sfxRequest+1            ; $9BEA
    lda     objY+7,x                ; $9BEC  on the tile row
    and     #$F0                    ; $9BEE
    sta     objY+7,x                ; $9BF0
    lda     projectileSpeed,x       ; $9BF2  landed before?
    bne     @burn                   ; $9BF5
    sta     objXVelocity+7,x        ; $9BF7  first time: stop,
    ldy     #$30                    ; $9BF9  3 in 4: burn for 48 frames
    lda     rng+1,x                 ; $9BFB
    and     #$03                    ; $9BFE
    bne     @setTimer               ; $9C00
    ldy     #$F0                    ; $9C02  1 in 4: roll toward Link,
    lda     drawScreenX+2           ; $9C04  left if right of him,
    cmp     drawScreenX             ; $9C06
    lda     #$02                    ; $9C08
    bcs     @setRoll                ; $9C0A
    lsr     a                       ; $9C0C  else right
    ldy     #$10                    ; $9C0D

@setRoll:
    sta     objFacing+7,x           ; $9C0F
    sty     objXVelocity+7,x        ; $9C11
    ldy     #$FF                    ; $9C13  for 255 frames

@setTimer:
    tya                             ; $9C15
    sta     projectileTimer,x       ; $9C16
    inc     projectileSpeed,x       ; $9C19  landed
    lda     #$F0                    ; $9C1C  a little hop
    sta     objYVelocity+7,x        ; $9C1E
    bne     Projectile_Fall_Bank5   ; $9C21

@burn:
    lda     projectileTimer,x       ; $9C23  time up?
    beq     Projectile_Kill_Bank5   ; $9C26
    dec     projectileTimer,x       ; $9C28
    beq     Projectile_Kill_Bank5   ; $9C2B
    and     #$07                    ; $9C2D  every 8 frames, slow down
    bne     Projectile_Straight_Bank5 ; $9C2F  by 1/16 toward 0
    lda     objXVelocity+7,x        ; $9C31
    beq     Projectile_Straight_Bank5 ; $9C33
    bpl     @slow                   ; $9C35
    inc     objXVelocity+7,x        ; $9C37
    inc     objXVelocity+7,x        ; $9C39

@slow:
    dec     objXVelocity+7,x        ; $9C3B

; ---------------------------------------------------------------------------
; Projectile_Straight_Bank5
;
; Projectile type 3 (a fire Octorok's shot), and the level flight of other
; types: move with Y velocity 0 (-2, then +2 below).
; Projectile_FallFast_Bank5 adds 2/16 pixel per frame to the Y velocity
; first, Projectile_Fall_Bank5 1/16.
;
; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_Straight_Bank5:
    lda     #$FE                    ; $9C3D  Y velocity -2, so that the
    sta     objYVelocity+7,x        ; $9C3F  +2 below leaves it at 0

Projectile_FallFast_Bank5:
    inc     objYVelocity+7,x        ; $9C42

Projectile_Fall_Bank5:
    inc     objYVelocity+7,x        ; $9C45

; ---------------------------------------------------------------------------
; Projectile_MoveAndCheck_Bank5
;
; Projectile types 1 and 2 (unused in this group), and the end of the
; others: move projectile x; remove it when it is off the top or bottom
; of the screen, or off a side (except type 7, which goes on unseen);
; else draw it (Projectile_Draw_Bank5) and test it against Link
; (Projectile_CheckLinkAlternate).
;
; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_MoveAndCheck_Bank5:
    jsr     Projectile_Move         ; $9C48
    lda     drawOffscreen+2         ; $9C4B  on screen?
    and     #$FC                    ; $9C4D
    beq     Projectile_DrawAndCheck_Bank5 ; $9C4F
    and     #$F0                    ; $9C51  off the top or bottom:
    bne     Projectile_Kill_Bank5   ; $9C53  remove
    lda     objState+7,x            ; $9C55  off a side: remove, unless
    cmp     #$07                    ; $9C57  type 7
    beq     Projectile_MoveAndCheck_Done_Bank5 ; $9C59

Projectile_Kill_Bank5:
    lda     #$00                    ; $9C5B
    sta     objState+7,x            ; $9C5D

Projectile_MoveAndCheck_Done_Bank5:
    rts                             ; $9C5F

Projectile_DrawAndCheck_Bank5:
    jsr     Projectile_Draw_Bank5   ; $9C60
    jsr     DoNothing               ; $9C63
    jmp     Projectile_CheckLinkAlternate ; $9C66

; ---------------------------------------------------------------------------
; Projectile_DeathSpark_Bank5
;
; Projectile type $0C, the sparks of a boss's death (Boss_SpawnDeathSpark_*):
; reached through the routine pointer one past the end of ProjectilePtrs_Bank5, whose
; bytes are ProjectileSparkPtrLo_Bank5 and the first of the flags table.  The
; spark stays where it was put; its X velocity ($10) only counts its 16
; frames down.  It is drawn as a pair (SpritePairTiles entry 0, a small
; spark) for 8 frames, then (entry 2, a larger ring) for 8, in palette 1,
; its last sprite mirrored, and never tested against Link.
;
; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_DeathSpark_Bank5:
    dec     objXVelocity+7,x        ; $9C69  count down; at 0, gone
    beq     Projectile_Kill_Bank5   ; $9C6B
    ldy     objOamOffset+7,x        ; $9C6D
    lda     objY+7,x                ; $9C6F
    sta     temp0                   ; $9C71
    lda     #$02                    ; $9C73
    sta     temp2                   ; $9C75
    lsr     a                       ; $9C77
    sta     temp3                   ; $9C78
    lsr     a                       ; $9C7A
    sta     drawOffscreen+1         ; $9C7B
    lda     objX+7,x                ; $9C7D
    sbc     scrollX                 ; $9C7F
    sta     temp1                   ; $9C82
    lda     objXVelocity+7,x        ; $9C84
    ldx     #$00                    ; $9C86
    cmp     #$08                    ; $9C88
    bcs     @draw                   ; $9C8A
    ldx     #$02                    ; $9C8C

@draw:
    jsr     Sprite_DrawPairFromTableKeepX ; $9C8E
    lda     #$41                    ; $9C91
    sta     oamBuffer - 2,y         ; $9C93

Projectile_DrawAndCheck_Done_Bank5:
    rts                             ; $9C96
; The rts byte is also the base of the table ProjectileFlipAttrs_Bank5 (entry 0 is the rts).
ProjectileFlipAttrs_Bank5 := Projectile_DrawAndCheck_Done_Bank5
    .byte   $40, $00                                                        ; $9C97

; ---------------------------------------------------------------------------
; Projectile_Draw_Bank5
;
; Draw projectile x, as Projectile_Draw_Bank1: one sprite at its Y and
; screen X, tile and attributes by its type (sramProjectileTiles,
; sramProjectileAttrs), mirrored when it faces right (ProjectileFlipAttrs),
; then its type's draw routine (sramProjectileDrawPtrs) with y = its OAM
; offset.  This group's: Flash for types 1, 4, 8; Flicker for 2, 5, 6;
; Spin for 3; Flame for 7; none (an rts) for 9.
;
; In:      x = projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_Draw_Bank5:
    lda     objState+7,x            ; $9C99
    pha                             ; $9C9B
    asl     a                       ; $9C9C
    tay                             ; $9C9D
    lda     sramProjectileDrawPtrs,y ; $9C9E  its routine
    sta     temp14                  ; $9CA1
    lda     sramProjectileDrawPtrs+1,y ; $9CA3
    sta     temp15                  ; $9CA6
    ldy     objOamOffset+7,x        ; $9CA8
    lda     objY+7,x                ; $9CAA  Y and screen X
    sta     oamBuffer,y             ; $9CAC
    lda     drawScreenX+2           ; $9CAF
    sta     oamBuffer+3,y           ; $9CB1
    pla                             ; $9CB4
    tay                             ; $9CB5
    lda     sramProjectileTiles,y   ; $9CB6  tile
    pha                             ; $9CB9
    lda     sramProjectileAttrs,y   ; $9CBA  attributes, flipped
    ldy     objFacing+7,x           ; $9CBD
    ora     ProjectileFlipAttrs_Bank5,y ; $9CBF
    ldy     objOamOffset+7,x        ; $9CC2
    sta     oamBuffer+2,y           ; $9CC4
    pla                             ; $9CC7
    sta     oamBuffer+1,y           ; $9CC8
    jmp     (temp14)                ; $9CCB  its draw routine

; ---------------------------------------------------------------------------
; Projectile_DrawFlame_Bank5
;
; Projectile type 7's draw (the Fokkeru's fireball): flashing in the air
; (Projectile_DrawFlash_Bank5).  Once it has landed (projectileSpeed set)
; it is a burning flame, tile $52, not flipped upside down, which blinks
; (hidden every other 2 frames) in its last 32 frames.
;
; In:      x = projectile index, y = its OAM offset
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_DrawFlame_Bank5:
    jsr     Projectile_DrawFlash_Bank5 ; $9CCE
    lda     projectileSpeed,x       ; $9CD1  landed?
    beq     @done                   ; $9CD4
    ldy     projectileTimer,x       ; $9CD6  its last 32 frames:
    cpy     #$20                    ; $9CD9
    bcs     @loc_9CEB               ; $9CDB
    lda     frameCounter            ; $9CDD  hidden every other 2 frames
    and     #$02                    ; $9CDF
    beq     @loc_9CEB               ; $9CE1
    ldy     objOamOffset+7,x        ; $9CE3
    lda     #$F8                    ; $9CE5
    sta     oamBuffer,y             ; $9CE7
    rts                             ; $9CEA

@loc_9CEB:
    ldy     objOamOffset+7,x        ; $9CEB  on the floor: not upside
    lda     oamBuffer+2,y           ; $9CED
    and     #$43                    ; $9CF0  down,
    sta     oamBuffer+2,y           ; $9CF2
    lda     #$52                    ; $9CF5  tile $52
    sta     oamBuffer+1,y           ; $9CF7

@done:
    rts                             ; $9CFA

; ---------------------------------------------------------------------------
; Projectile_DrawFlicker_Bank5
;
; Projectile draw: OR frameCounter bits 1-0 into its palette, a new color
; every frame.
;
; In:      y = its OAM offset
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_DrawFlicker_Bank5:
    lda     frameCounter            ; $9CFB  palette ORed with frameCounter
    and     #$03                    ; $9CFD
    ora     oamBuffer+2,y           ; $9CFF
    sta     oamBuffer+2,y           ; $9D02
    rts                             ; $9D05

; ---------------------------------------------------------------------------
; Projectile_DrawSpin_Bank5
;
; Projectile draw: tumble.  Palette 1, flipped horizontally when it faces
; right (objFacing bit 0) and vertically every other 4 frames
; (frameCounter bit 2).
;
; In:      x = projectile index, y = its OAM offset
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_DrawSpin_Bank5:
    lda     objFacing+7,x           ; $9D06  bit 6: facing right
    lsr     a                       ; $9D08
    lda     #$00                    ; $9D09
    ror     a                       ; $9D0B
    pha                             ; $9D0C
    lda     frameCounter            ; $9D0D  bit 7: frameCounter bit 2
    lsr     a                       ; $9D0F
    lsr     a                       ; $9D10

; Fokka_Ai: attack masks by enemy type, from $9D11 + $18: entries $18-$1A
; are FokkaThrowYOffsets 1-3, $00 (orange), $3F (red), $1F (blue).
FokkaAttackMasks:
    lsr     a                       ; $9D11
    pla                             ; $9D12
    ror     a                       ; $9D13
    ora     #$01                    ; $9D14
    bne     Projectile_SetAttr_Bank5 ; $9D16

; ---------------------------------------------------------------------------
; Projectile_DrawFlash_Bank5
;
; Projectile draw: palette 2, flipped horizontally every other 2 frames
; (frameCounter bit 1) and vertically every other 4 (bit 2).
; Projectile_SetAttr_Bank5 stores a as the attributes.
;
; In:      y = its OAM offset
; Status:  confirmed
; ---------------------------------------------------------------------------
Projectile_DrawFlash_Bank5:
    lda     frameCounter            ; $9D18  frameCounter bits 2, 1 to
    asl     a                       ; $9D1A
    asl     a                       ; $9D1B
    asl     a                       ; $9D1C
    sec                             ; $9D1D
    rol     a                       ; $9D1E
    asl     a                       ; $9D1F  bits 7, 6 (flips),
    and     #$C3                    ; $9D20  palette 2

Projectile_SetAttr_Bank5:
    sta     oamBuffer+2,y           ; $9D22
    rts                             ; $9D25

; Fokka jumps by facing (0 right, 1 left), doubled: 1.5 pixels per frame.
FokkaSpeeds:
    .byte   $0C, $F4                                                        ; $9D26

; Y offset of the Fokka's thrown sword: Y + 10 (pose 4, low), Y (pose 2,
; high).  Entries 1-3 are also FokkaAttackMasks $18-$1A.
FokkaThrowYOffsets:
    .byte   $0A, $00, $3F, $1F                                              ; $9D28

; ---------------------------------------------------------------------------
; Fokka_Ai
;
; Fokkas ($18 orange, $19 red, $1A blue): bird knights built on the Iron
; Knuckle's code, but always on the attack.  Each frame it faces Link.
;
; On the floor, 1 frame in 32 (rng+1,x bits 4-0 zero) it jumps at him:
; 3.5 pixels per frame up and 1.5 his way, keeping that X velocity until
; it lands (a ceiling turns it down at 1 pixel per frame).  Otherwise it
; doesn't approach: it moves at half Link's X velocity while he walks,
; else sways 1/4 pixel per frame (frameCounter bit 6, 64 frames each way).
;
; It attacks every 64 frames (red) or 32 (blue), by enemyAiState and
; FokkaAttackMasks; the orange's mask is 0, so it attacks whenever it is
; not attacking.  The count runs on the floor only while it isn't
; attacking, but always in the air.  An attack: 24 frames of wind-up at a
; random height (pose 1 high, 3 low), then the thrust (2, 4), on whose
; first frame it throws its sword (projectile type 5) from its Y (high) or
; Y + 10 (low).  Only if there is no free projectile slot does it thrust
; for 16 frames, testing the sword against Link (Weapon_CheckLink).
;
; Its shield (guard, enemyAiVar: 1 high, 0 low) goes to the height of
; Link's stroke whenever he presses B (high standing, low crouching), and
; while he is in the air to high if he is more than 5 pixels above it,
; else low.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Fokka_Ai:
    jsr     Enemy_Draw              ; $9D2C
    lda     objState+1,x            ; $9D2F  attacking?
    beq     @guard                  ; $9D31
    and     #$01                    ; $9D33  winding up (odd pose):
    bne     @checkTimer             ; $9D35  nothing to test
    jsr     Enemy_FireProjectile    ; $9D37  thrusting: throw the sword,
    tya                             ; $9D3A  2 px/frame the way it faces
    bmi     @testSword              ; $9D3B  (no slot: thrust instead)
    lda     #$05                    ; $9D3D  projectile type 5
    sta     a:objState+7,y          ; $9D3F
    lda     objState+1,x            ; $9D42  from Y (pose 2, high) or
    lsr     a                       ; $9D44  Y + 10 (pose 4, low)
    and     #$01                    ; $9D45
    tax                             ; $9D47
    lda     FokkaThrowYOffsets,x    ; $9D48
    ldx     currentObject           ; $9D4B
    clc                             ; $9D4D
    adc     objY+1,x                ; $9D4E
    sta     a:objY+7,y              ; $9D50
    lda     #$00                    ; $9D53  done
    sta     objState+1,x            ; $9D55

@testSword:
    jsr     Weapon_CheckLink        ; $9D57  the sword against Link

@checkTimer:
    lda     timerFast+TIMER_ENEMY,x ; $9D5A  pose over?
    bne     @toGuard                ; $9D5D
    inc     objState+1,x            ; $9D5F  next pose
    lda     objState+1,x            ; $9D61
    cmp     #$03                    ; $9D63  past 2 or 4: done
    beq     @endAttack              ; $9D65
    cmp     #$05                    ; $9D67
    bcs     @endAttack              ; $9D69
    lda     #$10                    ; $9D6B  thrust for 16 frames
    sta     timerFast+TIMER_ENEMY,x ; $9D6D

@toGuard:
    jmp     @guard                  ; $9D70
; (code below not executed in the test movies)

@endAttack:
    lda     #$00                    ; $9D73
    sta     objState+1,x            ; $9D75
; (end of code not executed in the test movies)

@guard:
    jsr     Enemy_CheckProjectileHitsSpecial ; $9D77  its shield (a clink returns)
    jsr     Enemy_UpdateBgCollision ; $9D7A
    ; Enemy_UpdateCommon, without drawing it again.
    ldy     #$01                    ; $9D7D
    inx                             ; $9D7F
    jsr     Obj_ComputeScreenPos    ; $9D80
    ldx     currentObject           ; $9D83
    lda     objYHi+1,x              ; $9D85  fallen below the screen?
    cmp     #$02                    ; $9D87
    bcc     @onScreen               ; $9D89
; (code below not executed in the test movies)
    jmp     Enemy_Despawn           ; $9D8B
; (end of code not executed in the test movies)

@onScreen:
    lda     drawOffscreen+1         ; $9D8E  off screen: no hit tests,
    and     #$FC                    ; $9D90  despawn if far
    beq     @hitTests               ; $9D92
    lda     objCollision+1,x        ; $9D94
    and     #$0F                    ; $9D96
    sta     objCollision+1,x        ; $9D98
    jsr     Enemy_DespawnIfFar      ; $9D9A
    jmp     @move                   ; $9D9D

@hitTests:
    jsr     Enemy_CheckProjectileHits ; $9DA0
    jsr     Enemy_CheckSwordHit     ; $9DA3
    jsr     Enemy_CheckLinkContact  ; $9DA6

@move:
    jsr     Enemy_HurtLinkOnContact ; $9DA9
    jsr     Enemy_MoveYAndFall      ; $9DAC  fall
    lda     objCollision+1,x        ; $9DAF  a ceiling: down at 1 px/frame
    and     #$08                    ; $9DB1
    beq     @checkFloor             ; $9DB3
    lda     #$10                    ; $9DB5
    sta     objYVelocity+1,x        ; $9DB7

@checkFloor:
    lda     objCollision+1,x        ; $9DBA
    and     #$04                    ; $9DBC
    beq     @walk                   ; $9DBE
    jsr     Enemy_Land              ; $9DC0

@walk:
    jsr     Enemy_KnockBackOrWalk_Bank5 ; $9DC3  move by last frame's velocity
    lda     a:joypadPressed         ; $9DC6  B pressed: shield to his
    and     #$40                    ; $9DC9  stroke's height
    beq     @checkJump              ; $9DCB
    lda     linkStanding            ; $9DCD
    sta     enemyAiVar,x            ; $9DCF

@checkJump:
    lda     linkJumpState           ; $9DD2  Link in the air:
    beq     @face                   ; $9DD5
    ldy     #$01                    ; $9DD7  high if he is more than 5
    lda     objY                    ; $9DD9  above, else low
    adc     #$05                    ; $9DDB
    cmp     objY+1,x                ; $9DDD
    bcc     @setGuard               ; $9DDF
    dey                             ; $9DE1

@setGuard:
    tya                             ; $9DE2
    sta     enemyAiVar,x            ; $9DE3

@face:
    jsr     Enemy_FaceLink          ; $9DE6
    lda     objCollision+1,x        ; $9DE9  on the floor?
    and     #$04                    ; $9DEB
    bne     @onFloor                ; $9DED
    beq     @countAttack            ; $9DEF  (in the air)

@onFloor:
    lda     rng+1,x                 ; $9DF1  1 frame in 32,
    and     #$1F                    ; $9DF4
    bne     @hold                   ; $9DF6
    lda     #$C8                    ; $9DF8  jump: 3.5 px/frame up,
    sta     objYVelocity+1,x        ; $9DFA
    dec     objY+1,x                ; $9DFD
    lda     FokkaSpeeds,y           ; $9DFF  1.5 toward Link
    asl     a                       ; $9E02
    sta     objXVelocity+1,x        ; $9E03
    rts                             ; $9E05

@hold:
    lda     objXVelocity            ; $9E06  Link's velocity while he
    bne     @setSpeed               ; $9E08  moves,
    ldy     #$08                    ; $9E0A  else sway, 64 frames each way
    lda     frameCounter            ; $9E0C
    and     #$40                    ; $9E0E
    bne     @swaySpeed              ; $9E10
    ldy     #$F8                    ; $9E12

@swaySpeed:
    tya                             ; $9E14

@setSpeed:
    sta     objXVelocity+1,x        ; $9E15  halved, keeping the sign
    asl     a                       ; $9E17
    ror     objXVelocity+1,x        ; $9E18
    lda     objState+1,x            ; $9E1A  attacking: done
    bne     @done                   ; $9E1C

@countAttack:
    ldy     enemyType,x             ; $9E1E  every 64 (red), 32 (blue) or
    lda     FokkaAttackMasks,y      ; $9E20  1 (orange) frames,
    inc     enemyAiState,x          ; $9E23
    and     enemyAiState,x          ; $9E25
    bne     @done                   ; $9E27
    lda     rng+1,x                 ; $9E29  attack: wind up high (1) or
    and     #$02                    ; $9E2C  low (3) at random,
    tay                             ; $9E2E
    iny                             ; $9E2F
    sty     objState+1,x            ; $9E30
    lda     #$18                    ; $9E32  for 24 frames
    sta     timerFast+TIMER_ENEMY,x ; $9E34

@done:
    rts                             ; $9E37

