; FokkaDrawXOffsets and FokkaDrawYOffsets, the X offset doubled for the
; middle of the thrust (timer 3-12), flipped upside down for the low thrust.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Fokka_Draw:
    lda     enemyAiVar,x            ; $9FD4
    ldy     #$00                    ; $9FD7
    cmp     #$00                    ; $9FD9
    bne     @loc_9FDF               ; $9FDB
    ldy     #$08                    ; $9FDD

@loc_9FDF:
    lda     objCollision+1,x        ; $9FDF
    and     #$04                    ; $9FE1
    bne     @loc_9FEE               ; $9FE3
    lda     objYVelocity+1,x        ; $9FE5
    bpl     @loc_A008               ; $9FE8
    ldy     #$10                    ; $9FEA
    bne     @loc_A008               ; $9FEC

@loc_9FEE:
    lda     objXVelocity+1,x        ; $9FEE
    beq     @loc_A008               ; $9FF0
    bpl     @loc_9FF9               ; $9FF2
    eor     #$FF                    ; $9FF4
    clc                             ; $9FF6
    adc     #$01                    ; $9FF7

@loc_9FF9:
    cmp     #$10                    ; $9FF9
    lda     #$08                    ; $9FFB
    bcc     @loc_A000               ; $9FFD
    lsr     a                       ; $9FFF

@loc_A000:
    and     frameCounter            ; $A000
    bne     @loc_A008               ; $A002
    iny                             ; $A004
    iny                             ; $A005
    iny                             ; $A006
    iny                             ; $A007

@loc_A008:
    tya                             ; $A008
    ldy     objOamOffset+1,x        ; $A009
    tax                             ; $A00B
    jsr     Sprite_DrawEnemyPair    ; $A00C
    jsr     Sprite_DrawEnemyPairKeepX ; $A00F
    lda     objState+1,x            ; $A012
    beq     @loc_A058               ; $A014
    sta     temp6                   ; $A016
    tax                             ; $A018
    lda     temp0                   ; $A019
    clc                             ; $A01B
    adc     FokkaDrawYOffsets,x     ; $A01C
    sta     temp0                   ; $A01F
    lda     temp2                   ; $A021
    cmp     #$01                    ; $A023
    bne     @loc_A02B               ; $A025
    inx                             ; $A027
    inx                             ; $A028
    inx                             ; $A029
    inx                             ; $A02A

@loc_A02B:
    lda     FokkaDrawXOffsets,x     ; $A02B
    ldx     currentObject           ; $A02E
    sty     temp7                   ; $A030
    ldy     timerFast+TIMER_ENEMY,x ; $A032
    cpy     #$03                    ; $A035
    bcc     @loc_A03E               ; $A037
    cpy     #$0D                    ; $A039
    bcs     @loc_A03E               ; $A03B
    asl     a                       ; $A03D

@loc_A03E:
    clc                             ; $A03E
    adc     temp1                   ; $A03F
    sta     temp1                   ; $A041
    ldy     temp7                   ; $A043
    ldx     temp6                   ; $A045
    cpx     #$04                    ; $A047
    bne     @loc_A051               ; $A049
    lda     temp3                   ; $A04B
    ora     #$80                    ; $A04D
    sta     temp3                   ; $A04F

@loc_A051:
    lda     FokkaDrawTiles,x        ; $A051
    tax                             ; $A054
    jmp     Sprite_DrawEnemyPairKeepX ; $A055

@loc_A058:
    ldx     currentObject           ; $A058
