Fokkeru_Draw:
    lda     enemyAiState,x          ; $A05B
    pha                             ; $A05D
    ldx     #$1C                    ; $A05E
    and     #$10                    ; $A060
    beq     @loc_A066               ; $A062
    ldx     #$24                    ; $A064

@loc_A066:
    pla                             ; $A066
    and     #$08                    ; $A067
    bne     @loc_A06F               ; $A069
    inx                             ; $A06B
    inx                             ; $A06C
    inx                             ; $A06D
    inx                             ; $A06E

