    jmp     Sprite_DrawEnemyPairKeepX ; $A072

; ---------------------------------------------------------------------------
; GpBubble_Ai
;
; Great Palace bubbles ($14 slow, $15 fast, $17 large): as Bubble_Ai
; (flying diagonally, bouncing off the screen's edges, walls, floors and
; ceilings, taking a point of Link's magic per contact), with 255 hit
; points.  A large bubble whose hit points fall below 192 splits: it doubles
; its speed and becomes a fast bubble, and puts a second fast bubble in the
; highest free enemy slot, 16 pixels right and 16-17 down, flying the
; same way across and the other way up or down (its Y velocity inverted,
; one less).  Both get 255 hit points.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
GpBubble_Ai:
    jsr     Enemy_SkipAiIfStunned   ; $A075  no AI while stunned
    jsr     Enemy_MoveX             ; $A078
    jsr     Enemy_MoveY             ; $A07B
    jsr     Enemy_UpdateWithBg      ; $A07E  probe background, draw, hit tests
    lda     objCollision+1,x        ; $A081  touching Link?
    and     #$10                    ; $A083
    beq     @hudRedraw              ; $A085
; (code below not executed in the test movies)
    lda     statMeter               ; $A087  a point of magic, down to 0
    sec                             ; $A08A
    sbc     #$01                    ; $A08B
    bcs     @setMagic               ; $A08D
    lda     #$00                    ; $A08F

@setMagic:
    sta     statMeter               ; $A091
; (end of code not executed in the test movies)

@hudRedraw:
    lda     hudRedraw               ; $A094  redraw the meters (every frame)
    ora     #$80                    ; $A097
    sta     hudRedraw               ; $A099
    jsr     Enemy_HurtLinkOnContact ; $A09C
    lda     enemyType,x             ; $A09F  a large bubble
    cmp     #$17                    ; $A0A1
    bne     @checkX                 ; $A0A3
    lda     enemyHp,x               ; $A0A5  below 192 hit points?
    cmp     #$C0                    ; $A0A7
    bcs     @checkX                 ; $A0A9
; (code below not executed in the test movies)
    asl     objXVelocity+1,x        ; $A0AB  split: twice as fast,
    asl     objYVelocity+1,x        ; $A0AD
    lda     #$15                    ; $A0B0  a fast bubble
    sta     enemyType,x             ; $A0B2
    ldy     #$05                    ; $A0B4  a free slot, from 5 down

@findSlot:
    lda     a:enemyActive,y         ; $A0B6
    beq     @newBubble              ; $A0B9
    dey                             ; $A0BB
    bpl     @findSlot               ; $A0BC
    bmi     @checkX                 ; $A0BE  (none: no second bubble)

@newBubble:
    lda     #$01                    ; $A0C0  active, on screen
    sta     a:enemyActive,y         ; $A0C2
    sta     a:objYHi+1,y            ; $A0C5
    lda     enemyHp,x               ; $A0C8
    sta     a:enemyHp,y             ; $A0CA
    lda     #$15                    ; $A0CD  a fast bubble
    sta     a:enemyType,y           ; $A0CF
    lda     objXVelocity+1,x        ; $A0D2  the same way across,
    sta     a:objXVelocity+1,y      ; $A0D4
    lda     objYVelocity+1,x        ; $A0D7  the other way up or down
    eor     #$FF                    ; $A0DA
    sta     objYVelocity+1,y        ; $A0DC
    lda     objY+1,x                ; $A0DF  16 pixels down
    adc     #$10                    ; $A0E1  (17 if flying up: the asl's carry)
    sta     a:objY+1,y              ; $A0E3
    lda     objX+1,x                ; $A0E6  and right
    adc     #$10                    ; $A0E8
    sta     a:objX+1,y              ; $A0EA
    lda     objXHi+1,x              ; $A0ED
    adc     #$00                    ; $A0EF
    sta     a:objXHi+1,y            ; $A0F1
    lda     #$FF                    ; $A0F4  both: 255 hit points
    sta     a:enemyHp,y             ; $A0F6
    sta     enemyHp,x               ; $A0F9
; (end of code not executed in the test movies)

@checkX:
    lda     drawOffscreen+1         ; $A0FB  off the side of the screen,
    and     #$0F                    ; $A0FD
    bne     @turn                   ; $A0FF
    lda     objCollision+1,x        ; $A101  or a wall ahead?
    and     #$03                    ; $A103
    beq     @checkY                 ; $A105

@turn:
    jsr     Enemy_TurnAround        ; $A107  turn around,
    jsr     Enemy_MoveX             ; $A10A  and step back

@checkY:
    lda     drawOffscreen+1         ; $A10D  off the top or bottom,
    and     #$F0                    ; $A10F
    bne     @bounceY                ; $A111
    lda     objCollision+1,x        ; $A113  or a floor or ceiling?
    and     #$0C                    ; $A115
    beq     GpFastBubble_Init_Done  ; $A117

@bounceY:
    lda     objYVelocity+1,x        ; $A119  reverse the Y velocity
    eor     #$FF                    ; $A11C
    clc                             ; $A11E
    adc     #$01                    ; $A11F
    sta     objYVelocity+1,x        ; $A121
    jmp     Enemy_MoveY             ; $A124  and step back

; ---------------------------------------------------------------------------
; GpSlowBubble_Init
;
; Spawn routine of slow bubbles ($14): 1 pixel per frame both ways, up and
; to the left.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
GpSlowBubble_Init:
    lda     #$F0                    ; $A127
    bne     GpBubble_SetSpeed       ; $A129

; ---------------------------------------------------------------------------
; GpFastBubble_Init
;
; Spawn routine of fast bubbles ($15) and large bubbles ($17): 2 pixels per
; frame both ways, up and to the left.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
GpFastBubble_Init:
    lda     #$E0                    ; $A12B

GpBubble_SetSpeed:
    sta     objXVelocity+1,x        ; $A12D
    sta     objYVelocity+1,x        ; $A12F

GpFastBubble_Init_Done:
    rts                             ; $A132

; ---------------------------------------------------------------------------
; LargeBubble_Draw
;
; Draw a large bubble: a flaming skull about 32 pixels across, made of
; mirrored pairs of sprites (SpritePairTiles entry $40), the palette
; changing every 2 frames.  Two rows are drawn at the bubble's position;
; a third, 24 pixels higher, only when the bubble is on screen.
;
; In:      x = enemy index, temp0/temp1 = its screen Y/X
; Status:  confirmed
; ---------------------------------------------------------------------------
LargeBubble_Draw:
    lda     #$02                    ; $A133
    sta     temp2                   ; $A135
    lda     frameCounter            ; $A137  palette from frameCounter bits 2-1
    lsr     a                       ; $A139
    and     #$03                    ; $A13A
    sta     temp3                   ; $A13C
    ldx     #$40                    ; $A13E
    lda     drawOffscreen+1         ; $A140
    pha                             ; $A142
    asl     drawOffscreen+1         ; $A143
    lda     temp1                   ; $A145  8 pixels right
    adc     #$08                    ; $A147
    sta     temp1                   ; $A149
    jsr     Sprite_DrawEnemyPair    ; $A14B
    jsr     Sprite_FlipPrevious     ; $A14E
    jsr     Sprite_DrawEnemyPair    ; $A151
    jsr     Sprite_FlipPrevious     ; $A154
    pla                             ; $A157  on screen?
    and     #$09                    ; $A158
    bne     @done                   ; $A15A
    lda     temp0                   ; $A15C  then a row 24 pixels up,
    sec                             ; $A15E
    sbc     #$18                    ; $A15F
    sta     temp0                   ; $A161
    lda     temp1                   ; $A163  8 pixels left
    sbc     #$08                    ; $A165
    sta     temp1                   ; $A167
    jsr     Sprite_DrawEnemyPairKeepX ; $A169
    jsr     Sprite_FlipPrevious     ; $A16C
    lda     oamBuffer - 1,y         ; $A16F  its last sprite 16 pixels right
    clc                             ; $A172
    adc     #$10                    ; $A173
    sta     oamBuffer - 1,y         ; $A175

@done:
    ldx     currentObject           ; $A178

LargeBubble_Draw_Done:
    rts                             ; $A17A
; Y offsets of the Bots a King Bot bursts into, by enemy slot 1-5 (entry 0
; is the rts above).
KingBotPartYOffsets := LargeBubble_Draw_Done
    .byte   $04, $08, $00, $08, $04                                         ; $A17B

; ---------------------------------------------------------------------------
; KingBot_Ai
;
; King Bot ($1E): a giant Bot.  It sleeps until it is on screen and Link
; comes within 48 pixels across; then it falls to the floor and hops
; toward him, 1 frame in 8 on the floor (1 pixel per frame across, 1.5 up),
; standing still between hops.  Below 48 hit points it bursts: enemy slots
; 5 down to 1 all become Bots (type $04, 208 hit points, stunned a frame),
; around its position (KingBotPart*Offsets), leaping 3 pixels per frame up
; and up to a pixel per frame either way across.  Slot 5 is written first,
; so a King Bot there (where it spawns) moves itself 9 pixels right and 4
; down before the others are placed around it.
;
; BUG: the burst fills slots 1-5 whatever is in them, and leaves slot 0
; alone.  A King Bot in slots 1-5 becomes one of the Bots, but one in slot
; 0 stays a King Bot and bursts again every frame, so the Bots are put back
; in place each frame and never move; it no longer hits Link or can be
; hit.  Enemies spawn into the highest free slot, so the two King Bots,
; alone in their rooms, take slot 5.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
KingBot_Ai:
    lda     enemyHp,x               ; $A180  below 48 hit points?
    cmp     #$30                    ; $A182
    bcs     @awake                  ; $A184
    ldy     #$05                    ; $A186  burst into slots 5-1

@burst:
    lda     #$04                    ; $A188  a Bot,
    sta     a:enemyType,y           ; $A18A
    lda     #$01                    ; $A18D  active, on screen,
    sta     a:enemyActive,y         ; $A18F
    sta     enemyStunTimer,y        ; $A192  stunned a frame
    sta     a:objYHi+1,y            ; $A195
    lsr     a                       ; $A198
    sta     a:objCollision+1,y      ; $A199
    lda     objX+1,x                ; $A19C  around the King Bot
    adc     KingBotPartXOffsets,y   ; $A19E
    sta     a:objX+1,y              ; $A1A1
    lda     objXHi+1,x              ; $A1A4
    adc     KingBotPartXHiOffsets,y ; $A1A6
    sta     a:objXHi+1,y            ; $A1A9
    lda     objY+1,x                ; $A1AC
    adc     KingBotPartYOffsets,y   ; $A1AE
    sta     a:objY+1,y              ; $A1B1
    lda     #$D0                    ; $A1B4  leaping 3 pixels per frame,
    sta     objYVelocity+1,y        ; $A1B6
    sta     a:enemyHp,y             ; $A1B9  208 hit points
    lda     rng+2,y                 ; $A1BC  and -1..+1 across, at random
    and     #$1F                    ; $A1BF
    adc     #$F0                    ; $A1C1
    sta     a:objXVelocity+1,y      ; $A1C3
    dey                             ; $A1C6
    bne     @burst                  ; $A1C7  (not slot 0)

@done:
    rts                             ; $A1C9

@awake:
    lda     objState+1,x            ; $A1CA  awake?
    bne     @fall                   ; $A1CC
    lda     drawOffscreen+1         ; $A1CE  else wait until on screen
    bne     @done                   ; $A1D0
    jsr     Enemy_FaceLink          ; $A1D2  and Link within 48 pixels
    lda     temp15                  ; $A1D5
    adc     #$30                    ; $A1D7
    cmp     #$60                    ; $A1D9
    bcs     @done                   ; $A1DB
    inc     objState+1,x            ; $A1DD  wake

@fall:
    lda     objCollision+1,x        ; $A1DF  on the floor?
    and     #$04                    ; $A1E1
    beq     @move                   ; $A1E3
; (code below not executed in the test movies)
    jsr     Enemy_Land              ; $A1E5  stand on it

@setYVelocity:
    sta     objYVelocity+1,x        ; $A1E8
; (end of code not executed in the test movies)

@move:
    jsr     Enemy_MoveYAndFall      ; $A1EB
    jsr     Enemy_UpdateWithBg      ; $A1EE  probe background, draw, hit tests
    lda     objCollision+1,x        ; $A1F1  on the floor?
    and     #$04                    ; $A1F3
    beq     @moveX                  ; $A1F5
; (code below not executed in the test movies)
    lda     rng+1,x                 ; $A1F7  1 frame in 8,
    and     #$07                    ; $A1FA
    bne     @hurtLink               ; $A1FC  (else stand still)
    jsr     Enemy_FaceLink          ; $A1FE  hop toward Link:
    lda     KingBotSpeeds,y         ; $A201  1 pixel per frame across,
    sta     objXVelocity+1,x        ; $A204
    lda     #$E8                    ; $A206  1.5 up
    bne     @setYVelocity           ; $A208
; (end of code not executed in the test movies)

@moveX:
    jsr     Enemy_MoveX             ; $A20A  across while in the air

@hurtLink:
    jmp     Enemy_HurtLinkOnContact ; $A20D

; PPU strings for the barrier's colors (background palette 2): two
; flashing sets, each followed by one with the last two colors black;
; Barrier_Ai writes the next one every 4 frames, and the first once more
; when it starts to dissolve.
BarrierPaletteStrings:
    .byte   $3F, $08, $04, $0F, $17, $16, $22, $FF, $3F, $08, $04, $0F, $17, $0F, $0F, $FF; $A210
    .byte   $3F, $08, $04, $0F, $17, $22, $16, $FF, $3F, $08, $04, $0F, $17, $0F, $0F, $FF; $A220
; (unreferenced: $A230-$A233, 4 bytes)
    .byte   $04, $05, $06, $04                                              ; $A230

; ---------------------------------------------------------------------------
; Barrier_Ai
;
; The barrier ($20) at the Great Palace's entrance, at X $110, a wall of
; flashing tiles drawn by the area (it has no sprites).  While it is on
; screen it hurts Link on contact, clearing his invulnerability so it can
; hurt him again on each contact frame, and a fairy Link dies at once.
;
; It opens when all crystals are placed (crystalsRemaining = 0), it is on
; screen and Link reaches X $C0 on page 0: the game freezes (gameFrozen;
; the barrier keeps running) with sound $40, and the barrier
; dissolves from the bottom up.  Every 4 frames it blanks a 12-tile row
; of the name table (tile $F4), from $26A2 up to $2502; every 8 frames it
; also clears 7 blocks of a row of the area map (sramAreaTiles, page 1,
; columns 1-7) to $40, rows 8 up to 2.  After 14 rows (56 frames) the game
; unfreezes.  The dissolve keeps its PPU address in enemy slot 3's
; objX/objXHi and its map offset in objState+4 (the barrier's room uses no
; slot 3), and counts frames in its own objXVelocity.  It stays in state
; 3, shifting gameFrozen right each frame after.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Barrier_Ai:
    lda     enemyAiState,x          ; $A234  dissolving?
    bne     @dissolve               ; $A236
    lda     crystalsRemaining       ; $A238  all crystals placed and on
    ora     drawOffscreen+1         ; $A23B  screen?
    bne     @onScreen               ; $A23D
    lda     objXHi                  ; $A23F  Link on page 0, X >= $C0?
    bne     @onScreen               ; $A241
    lda     objX                    ; $A243
    cmp     #$C0                    ; $A245
    bcc     @onScreen               ; $A247
    rol     gameFrozen              ; $A249  freeze the game (carry set)
    lda     #$00                    ; $A24B
    sta     objXVelocity+1,x        ; $A24D  frame count
    sta     objXHi+4                ; $A24F  no PPU address yet
    sta     objX+4                  ; $A251
    sta     objState+4              ; $A253
    lda     #$40                    ; $A255  sound
    sta     sfxRequest              ; $A257
    lda     #$03                    ; $A259  dissolving (state 3)
    sta     enemyAiState,x          ; $A25B
    sta     objState                ; $A25D  and Link's state 3

@onScreen:
    lda     drawOffscreen+1         ; $A25F  on screen and Link alive?
    ora     linkDeathPending        ; $A261
    bne     @flash                  ; $A264
    sta     timerSlow+TIMER_INVULNERABLE ; $A266  no invulnerability
    jsr     Enemy_CheckLinkContact  ; $A269
    jsr     Enemy_HurtLinkOnContact ; $A26C
    lda     objCollision+1,x        ; $A26F  touching Link
    and     #$10                    ; $A271
    beq     @flash                  ; $A273
; (code below not executed in the test movies)
    lda     linkFairy               ; $A275  as a fairy?
    beq     @flash                  ; $A277
    inc     linkDeathPending        ; $A279  he dies
; (end of code not executed in the test movies)

@flash:
    lda     #$00                    ; $A27C  starting to dissolve: the
    ldy     enemyAiState,x          ; $A27E  first string
    bne     @writeColors            ; $A280
    lda     frameCounter            ; $A282  else every 4 frames,
    and     #$03                    ; $A284
    bne     @done                   ; $A286
    lda     frameCounter            ; $A288  the next string
    and     #$0C                    ; $A28A
    asl     a                       ; $A28C

@writeColors:
    tax                             ; $A28D
    ldy     #$00                    ; $A28E

@copyColors:
    lda     BarrierPaletteStrings,x ; $A290
    sta     ppuBuffer1,y            ; $A293
    inx                             ; $A296
    iny                             ; $A297
    cpy     #$08                    ; $A298
    bne     @copyColors             ; $A29A
    lda     #$07                    ; $A29C
    sta     ppuBuffer1Len           ; $A29E
    lda     #$01                    ; $A2A1  write ppuBuffer1
    sta     ppuStringSelect         ; $A2A3

@done:
    rts                             ; $A2A6

@dissolve:
    lda     objXHi+4                ; $A2A7  first frame: start at the
    bne     @checkDone              ; $A2A9  bottom row
    lda     #$81                    ; $A2AB  (map row 8, column 1)
    sta     objState+4              ; $A2AD
    lda     #$A2                    ; $A2AF  (name table $26A2)
    sta     objX+4                  ; $A2B1
    lda     #$26                    ; $A2B3
    sta     objXHi+4                ; $A2B5

@checkDone:
    cmp     #$24                    ; $A2B7  past the top row ($24E2)?
    bne     @nextFrame              ; $A2B9
    lda     objX+4                  ; $A2BB
    cmp     #$E2                    ; $A2BD
    bne     @nextFrame              ; $A2BF
    lsr     gameFrozen              ; $A2C1  then unfreeze

@done2:
    rts                             ; $A2C3

@nextFrame:
    inc     objXVelocity+1,x        ; $A2C4  every 4 frames
    lda     objXVelocity+1,x        ; $A2C6
    and     #$03                    ; $A2C8
    bne     @done2                  ; $A2CA
    lda     objXVelocity+1,x        ; $A2CC  and every 8th,
    and     #$04                    ; $A2CE
    beq     @blankRow               ; $A2D0
    ldy     objState+4              ; $A2D2  clear a row of the map
    ldx     #$06                    ; $A2D4  (7 blocks)
    lda     #$40                    ; $A2D6

@clearBlocks:
    sta     sramAreaTiles+208,y     ; $A2D8
    iny                             ; $A2DB
    dex                             ; $A2DC
    bpl     @clearBlocks            ; $A2DD
    lda     objState+4              ; $A2DF  and go up a row
    sec                             ; $A2E1
    sbc     #$10                    ; $A2E2
    sta     objState+4              ; $A2E4

@blankRow:
    lda     objXHi+4                ; $A2E6  blank a row of 12 tiles
    sta     ppuBuffer1              ; $A2E8
    lda     objX+4                  ; $A2EB
    sta     ppuBuffer1+1            ; $A2ED
    ldx     #$0C                    ; $A2F0
    stx     ppuBuffer1+2            ; $A2F2
    lda     #$FF                    ; $A2F5
    sta     ppuBuffer1+15           ; $A2F7
    dex                             ; $A2FA

@fillRow:
    lda     #$F4                    ; $A2FB
    sta     ppuBuffer1+3,x          ; $A2FD
    dex                             ; $A300
    bpl     @fillRow                ; $A301
    lda     objX+4                  ; $A303  and go up a row
    sec                             ; $A305
    sbc     #$20                    ; $A306
    sta     objX+4                  ; $A308
    lda     objXHi+4                ; $A30A
    sbc     #$00                    ; $A30C
    sta     objXHi+4                ; $A30E
    lda     #$0F                    ; $A310
    sta     ppuBuffer1Len           ; $A312
    lda     #$01                    ; $A315  write ppuBuffer1
    sta     ppuStringSelect         ; $A317
    ldx     currentObject           ; $A31A
    rts                             ; $A31C
; (disassembled with tools/disasm.py; not executed in the test movies)

; ---------------------------------------------------------------------------
; Generator_Init_Bank5
;
; Spawn routine of the fire Bago Bago generator ($0F), as
; Generator_Init_Bank4: despawn any other enemy of its type, so only one
; generator runs.  Rooms $03 and $32 each place two, on pages 0 and 3:
; the second, when it spawns, removes the first.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Generator_Init_Bank5:
    ldy     #$05                    ; $A31D  every other slot:

@loop:
    cpy     currentObject           ; $A31F
    beq     @loc_A32F               ; $A321
    lda     a:enemyActive,y         ; $A323  active,
    beq     @loc_A32F               ; $A326
    lda     a:enemyType,y           ; $A328  of this type?
    cmp     enemyType,x             ; $A32B
    beq     @loc_A333               ; $A32D

@loc_A32F:
    dey                             ; $A32F
    bpl     @loop                   ; $A330
    rts                             ; $A332

@loc_A333:
    tya                             ; $A333  yes: remove it
    tax                             ; $A334
    jsr     Enemy_Despawn           ; $A335
    ldx     currentObject           ; $A338
    rts                             ; $A33A
; (end of disassembled code)


; ---------------------------------------------------------------------------
; Thunderbird_Init
;
; Spawn routine of the Thunderbird ($22): only while the area's flag is set
; (not yet beaten), else removed at once.  It starts drifting down at 1/2
; pixel per frame.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Thunderbird_Init:
    ldx     #$01                    ; $A33B  beaten already?
    jsr     Area_TestFlag           ; $A33D
    ldx     currentObject           ; $A340
    cmp     #$00                    ; $A342
    bne     @place                  ; $A344
; (code below not executed in the test movies)
    sta     enemyActive,x           ; $A346  yes: gone
    rts                             ; $A348
; (end of code not executed in the test movies)

@place:
    lda     #$08                    ; $A349
    sta     objYVelocity+1,x        ; $A34B
    rts                             ; $A34E

; Thunderbird: X velocity toward Link by facing (0 right, 1 left).
ThunderbirdSpeeds:
    .byte   $10, $F0                                                        ; $A34F

; Thunderbird fireballs: X velocity by rng+2 bits 2-0, 1/8 to 1 pixel per
; frame either way.
ThunderbirdShotSpeeds:
    .byte   $02, $04, $08, $10, $FE, $FC, $F8, $F0                          ; $A351

; ---------------------------------------------------------------------------
; Thunderbird_Ai
;
; The Thunderbird ($22), the Great Palace's boss, with the bank 4 bosses'
; intro and death (as Boss_UpdateIntro, inline):
; - Until Link's screen reaches page 1 of the room (scrollXHi), it is only
;   drawn.  Then the scroll freezes, and it waits 144 frames.
; - Dying (its type's hitbox $FF), it is only drawn while its stun
;   flashes.  Then every projectile is removed, every other living enemy
;   takes a hit at level $0A (224 points), and the music stops.
; - With 192 hit points or more it is only drawn, with no hit tests: Link
;   can't hurt it until the Thunder spell, which does it 2 points (flags
;   bit 5), brings it below 192.  Its body never hurts Link (it doesn't
;   call Enemy_HurtLinkOnContact); only its fireballs do.
; - While Link isn't mid-stroke (linkAttackFrame 0) it moves his sword
;   out of the hit tests (swordY = $F8).
;
; It flies toward Link at 1 pixel per frame, turning every 32 frames, and
; bobs: its Y velocity swings between 1 pixel per frame up and down, by
; 1/16 every 4 frames, 64 pixels each way every 256 frames.  Every 32
; frames (16 below 96 hit points) it spits a fireball (projectile type 8)
; from 12 pixels right of its X, 1 pixel per frame up and 1/8 to 1
; either way at random (ThunderbirdShotSpeeds), falling with gravity.
;
; BUG: the intro and death paths drop the AI's return address with
; pla/pla as Boss_UpdateIntro does, but here they are in the AI routine
; itself, so they drop Enemies_Update's: the enemy slots after the
; Thunderbird's, and its projectile slot, are not updated in those frames.
; Its room has no other enemies.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
Thunderbird_Ai:
    lda     scrollFrozen            ; $A359  fight on already?
    bne     @fightOn                ; $A35C
    lda     scrollXHi               ; $A35E  Link not yet at page 1:
    beq     @drawOnly               ; $A361  just draw it
    inc     scrollFrozen            ; $A363  scroll frozen,
    lda     #$90                    ; $A366  wait 144 frames
    sta     timerFast+TIMER_ENEMY,x ; $A368

@fightOn:
    lda     sramEnemyHitbox+34      ; $A36B  dying (hitbox $FF)?
    bpl     @alive                  ; $A36E
    ldy     enemyStunTimer,x        ; $A370  still flashing: draw it
    bne     @drawOnly               ; $A373
    inc     enemyActive,x           ; $A375  burst
    lda     #$0A                    ; $A377
    sta     drawScratch             ; $A379
    lda     currentObject           ; $A37B
    pha                             ; $A37D
    ldx     #$05                    ; $A37E  every slot:

@loop:
    stx     currentObject           ; $A380
    lda     #$00                    ; $A382  projectile gone
    sta     objState+7,x            ; $A384
    lda     enemyActive,x           ; $A386  a living enemy:
    beq     @next                   ; $A388
    cmp     #$01                    ; $A38A
    bne     @next                   ; $A38C
; (code below not executed in the test movies)
    inx                             ; $A38E
    ldy     #$01                    ; $A38F
    jsr     Obj_ComputeScreenPos    ; $A391
    ldx     currentObject           ; $A394
    ldy     drawScratch             ; $A396  (always $0A)
    bne     @hit                    ; $A398
    lda     drawOffscreen+1         ; $A39A
    and     #$88                    ; $A39C
    bne     @next                   ; $A39E
    ldy     enemyType,x             ; $A3A0
    lda     sramEnemyFlags,y        ; $A3A2
    ldy     #$09                    ; $A3A5
    and     #$A0                    ; $A3A7
    bmi     @next                   ; $A3A9
    beq     @hit                    ; $A3AB
    ldy     #$01                    ; $A3AD

@hit:
    jsr     Enemy_TakeDamage        ; $A3AF  takes a hit
; (end of code not executed in the test movies)

@next:
    dex                             ; $A3B2
    bpl     @loop                   ; $A3B3
    pla                             ; $A3B5
    sta     currentObject           ; $A3B6
    tax                             ; $A3B8
    lda     #$80                    ; $A3B9  music off
    sta     musicRequest            ; $A3BB

@drawOnly:
    pla                             ; $A3BD  BUG: drops Enemies_Update's
    pla                             ; $A3BE  return (see above)
    jmp     Enemy_Draw              ; $A3BF

@alive:
    lda     linkAttackFrame         ; $A3C2  Link not mid-stroke: no sword
    bne     @checkHp                ; $A3C5
    lda     #$F8                    ; $A3C7
    sta     swordY                  ; $A3C9

@checkHp:
    lda     enemyHp,x               ; $A3CC  192 or more: just draw
    cmp     #$C0                    ; $A3CE  (no hit tests)
    bcc     @hitTests               ; $A3D0
    jsr     Enemy_Draw              ; $A3D2
    jmp     @checkKilled            ; $A3D5

@hitTests:
    jsr     Enemy_UpdateCommon      ; $A3D8

@checkKilled:
    lda     #$01                    ; $A3DB  killed (Enemy_Kill made it
    cmp     enemyActive,x           ; $A3DD  ENEMY_STATE_DYING)?
    beq     @checkWait              ; $A3DF
    sta     enemyActive,x           ; $A3E1  then keep it active, dying:
    lda     #$FF                    ; $A3E3  hitbox $FF,
    sta     sramEnemyHitbox+34      ; $A3E5
    sta     timerFast+TIMER_ENEMY,x ; $A3E8
    lsr     a                       ; $A3EB  flashing 127 frames
    sta     enemyStunTimer,x        ; $A3EC

@checkWait:
    lda     timerFast+TIMER_ENEMY,x ; $A3EF  waiting?
    beq     @act                    ; $A3F2
    rts                             ; $A3F4

@act:
    lda     #$18                    ; $A3F5  hit point bar, 24 per unit
    jsr     Boss_DrawHpBar_Bank5    ; $A3F7
    lda     frameCounter            ; $A3FA  (a test that branches to the
    bne     @shotMask               ; $A3FC  next instruction either way)

@shotMask:
    lda     #$1F                    ; $A3FE  every 32 frames,
    ldy     enemyHp,x               ; $A400  16 below 96 hit points:
    cpy     #$60                    ; $A402
    bcs     @checkShot              ; $A404
    lsr     a                       ; $A406

@checkShot:
    and     frameCounter            ; $A407
    bne     @move                   ; $A409
    jsr     Enemy_FireProjectile    ; $A40B  a fireball
    bcs     @move                   ; $A40E
    lda     #$08                    ; $A410  projectile type 8,
    sta     a:objState+7,y          ; $A412
    lda     objX+1,x                ; $A415  12 pixels right,
    adc     #$0C                    ; $A417
    sta     a:objX+7,y              ; $A419
    lda     objXHi+1,x              ; $A41C
    adc     #$00                    ; $A41E
    sta     a:objXHi+7,y            ; $A420
    lda     rng+2                   ; $A423  at a random speed across,
    and     #$07                    ; $A426
    tax                             ; $A428
    lda     ThunderbirdShotSpeeds,x ; $A429
    sta     a:objXVelocity+7,y      ; $A42C
    lda     #$F0                    ; $A42F  1 pixel per frame up
    sta     objYVelocity+7,y        ; $A431
    ldx     currentObject           ; $A434

@move:
    jsr     Enemy_MoveX             ; $A436
    jsr     Enemy_MoveY             ; $A439
    lda     frameCounter            ; $A43C  every 4 frames: bob
    and     #$03                    ; $A43E
    bne     @checkTurn              ; $A440
    lda     objYVelocity+1,x        ; $A442  at 1 px/frame either way,
    cmp     #$10                    ; $A445  turn the other way
    beq     @turnY                  ; $A447
    cmp     #$F0                    ; $A449
    bne     @accelY                 ; $A44B

@turnY:
    inc     enemyAiState,x          ; $A44D

@accelY:
    lda     enemyAiState,x          ; $A44F  +1/16 (odd state) or -1/16
    lsr     a                       ; $A451
    inc     objYVelocity+1,x        ; $A452
    bcs     @checkTurn              ; $A455
    dec     objYVelocity+1,x        ; $A457
    dec     objYVelocity+1,x        ; $A45A

@checkTurn:
    lda     frameCounter            ; $A45D  every 32 frames: toward Link
    and     #$1F                    ; $A45F
    bne     @done                   ; $A461
    jsr     Enemy_FaceLink          ; $A463
    lda     ThunderbirdSpeeds,y     ; $A466
    sta     objXVelocity+1,x        ; $A469

@done:
    rts                             ; $A46B

; OldMan_Draw: the Triforce's X and Y offsets, by phase 0-5, 6, 7.
TriforceXOffsets:
    .byte   $10, $00, $EC                                                   ; $A46C

TriforceYOffsets:
    .byte   $00, $F0, $E0                                                   ; $A46F

; ---------------------------------------------------------------------------
; OldMan_Draw
;
; Draw routine of type $23, used by DarkLink_Ai through Enemy_Draw before
; and after the fight (Dark Link itself is drawn by DarkLink_Draw): the old
; man, at Dark Link's position, and the Triforce.  The old man is
; SpritePairTiles entry $36, or $38 one frame count in four (enemyAiState
; bits 4-3 zero, 8 frames of every 32).  The Triforce is entry $3A in
; palette 3 (glowing, Triforce_FlashPalette), its right sprite mirrored,
; placed by phase (TriforceXOffsets, TriforceYOffsets): 16 pixels right of
; him, sitting on the pillar (phases 0-1); 16 above him (6); 32 above and
; 20 left, in Link's raised hands (7).
;
; In:      x = 0 (Dark Link's slot)
; Status:  confirmed
; ---------------------------------------------------------------------------
OldMan_Draw:
    lda     #$02                    ; $A472
    sta     temp2                   ; $A474
    ldx     #$36                    ; $A476  the old man: $36,
    lda     enemyAiState            ; $A478
    and     #$18                    ; $A47A
    bne     @drawLeft               ; $A47C
    inx                             ; $A47E  or $38 a quarter of the time
    inx                             ; $A47F

@drawLeft:
    jsr     Sprite_DrawEnemyPairKeepX ; $A480
    ldx     #$00                    ; $A483  offsets by phase: 0-5,
    lda     objFacing+4             ; $A485
    cmp     #$06                    ; $A487
    bcc     @placeRight             ; $A489
    inx                             ; $A48B  6,
    cmp     #$07                    ; $A48C
    bne     @placeRight             ; $A48E
    inx                             ; $A490  7

@placeRight:
    lda     objY+1                  ; $A491
    clc                             ; $A493
    adc     TriforceYOffsets,x      ; $A494
    sta     temp0                   ; $A497
    lda     drawScreenX+1           ; $A499
    clc                             ; $A49B
    adc     TriforceXOffsets,x      ; $A49C
    sta     temp1                   ; $A49F
    lda     drawOffscreen+1         ; $A4A1
    asl     a                       ; $A4A3
    asl     a                       ; $A4A4
    and     #$0F                    ; $A4A5
    sta     drawOffscreen+1         ; $A4A7
    lda     #$03                    ; $A4A9  palette 3
    sta     temp3                   ; $A4AB
    ldx     #$3A                    ; $A4AD  the Triforce: $3A,
    jsr     Sprite_DrawEnemyPairKeepX ; $A4AF
    lda     #$43                    ; $A4B2  its last sprite mirrored
    sta     oamBuffer - 2,y         ; $A4B4
    rts                             ; $A4B7

; Sprite palette 3 (its color 2 replaced by TriforceFlashColors).
TriforceFlashString:
    .byte   $3F, $1C, $04, $0F, $30, $30, $30, $FF                          ; $A4B8

TriforceFlashColors:
    .byte   $17, $27, $37, $37                                              ; $A4C0

; ---------------------------------------------------------------------------
; Triforce_FlashPalette
;
; Every frame of DarkLink_Ai: queue sprite palette 3 as $0F, $30, x, $30,
; x cycling $17, $27, $37, $37 every 4 frames (TriforceFlashColors), so the
; Triforce (drawn in palette 3) glows.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Triforce_FlashPalette:
    ldx     ppuBuffer0Len           ; $A4C4  append TriforceFlashString
    ldy     #$00                    ; $A4C7

@loop:
    lda     TriforceFlashString,y   ; $A4C9
    sta     ppuBuffer0,x            ; $A4CC
    inx                             ; $A4CF
    iny                             ; $A4D0
    cpy     #$08                    ; $A4D1
    bcc     @loop                   ; $A4D3
    lda     frameCounter            ; $A4D5  its color by frameCounter
    lsr     a                       ; $A4D7  bits 3-2
    lsr     a                       ; $A4D8
    and     #$03                    ; $A4D9
    tay                             ; $A4DB
    lda     TriforceFlashColors,y   ; $A4DC
    sta     ppuBuffer0-3,x          ; $A4DF  its color 2
    dex                             ; $A4E2  (the next string overwrites
    stx     ppuBuffer0Len           ; $A4E3  the $FF)
    ldx     currentObject           ; $A4E6
    rts                             ; $A4E8

; ---------------------------------------------------------------------------
; Boss_DrawHpBar_Bank5
;
; Bank 5's copy of Boss_DrawHpBar (bank 4): a column of 8 sprites at X
; $10 from Y $70 up, ceil(hit points / a) full ($6E), the rest empty ($70),
; palette 1.  The Thunderbird uses a = 24, Dark Link 1.
;
; In:      x = enemy index, a = hit points per block
; Status:  confirmed
; ---------------------------------------------------------------------------
Boss_DrawHpBar_Bank5:
    sta     temp0                   ; $A4E9
    ldy     #$00                    ; $A4EB  y = ceil(hp / a)
    lda     enemyHp,x               ; $A4ED
    clc                             ; $A4EF

@loop:
    sbc     temp0                   ; $A4F0
    iny                             ; $A4F2
    bcs     @loop                   ; $A4F3
    ldx     #$1C                    ; $A4F5  8 sprites, bottom first,
    lda     #$70                    ; $A4F7  from Y $70
    sta     temp0                   ; $A4F9

@loop2:
    lda     #$70                    ; $A4FB  empty,
    dey                             ; $A4FD
    bmi     @loc_A502               ; $A4FE
    lda     #$6E                    ; $A500  or full

@loc_A502:
    sta     oamBuffer+193,x         ; $A502
    lda     #$01                    ; $A505  palette 1
    sta     oamBuffer+194,x         ; $A507
    lda     #$10                    ; $A50A  X $10
    sta     oamBuffer+195,x         ; $A50C
    lda     temp0                   ; $A50F
    sta     oamBuffer+192,x         ; $A511
    adc     #$F8                    ; $A514  next up: 8 higher, then 7 (carry)
    sta     temp0                   ; $A516
    dex                             ; $A518
    dex                             ; $A519
    dex                             ; $A51A
    dex                             ; $A51B
    bpl     @loop2                  ; $A51C
    ldx     currentObject           ; $A51E
    rts                             ; $A520

; ---------------------------------------------------------------------------
; HiddenJar_Ai_Bank5
;
; Hidden object ($05, Great Palace): invisible and still until Link's
; sword strikes it.  Then half the time (rng+1,x bit 7) it is a red Fokka
; ($19, 48 hit points), and otherwise a red jar (type $01, kind $11); either
; is stunned 8 frames and moved 3 pixels right.  The Fokka keeps the jar's
; kind in enemyAiState.
;
; In:      x = enemy index
; Status:  confirmed
; ---------------------------------------------------------------------------
HiddenJar_Ai_Bank5:
    lda     drawOffscreen+1         ; $A521  on screen?
    bne     @done                   ; $A523
    jsr     Enemy_CheckSwordHit     ; $A525
    lda     objCollision+1,x        ; $A528  struck?
    and     #$20                    ; $A52A
    beq     @done                   ; $A52C
    lda     #$11                    ; $A52E  kind $11, a red jar
    sta     enemyAiState,x          ; $A530
    ldy     #$01                    ; $A532  an item, 1 hit point
    sty     enemyHp,x               ; $A534
    lda     rng+1,x                 ; $A536
    bpl     @setType                ; $A539
; (code below not executed in the test movies)
    lda     #$30                    ; $A53B  or half the time a red Fokka,
