    ldy     #$19                    ; $A53F
; (end of code not executed in the test movies)

@setType:
    sty     enemyType,x             ; $A541
    lda     #$08                    ; $A543  stunned 8 frames
    sta     enemyStunTimer,x        ; $A545
    lda     objX+1,x                ; $A548
    adc     #$03                    ; $A54A
    sta     objX+1,x                ; $A54C

@done:
    rts                             ; $A54E
; (unreferenced: $A54F-$A5FF, 177 bytes)
