; ---------------------------------------------------------------------------
; Game_PowerOnInit
;
; Power-on initialization, called by Main: repair the save files, clear
; RAM, silence and enable the sound channels, turn rendering off, hide the
; sprites, clear the nametables, and switch the NMI to Bank5_Nmi for the
; title screen.
;
; Clobbers: a, x, y
; Status:  confirmed
; ---------------------------------------------------------------------------
Game_PowerOnInit:
    jsr     Save_CheckFiles         ; $A6A0
    jsr     Ram_ClearAll            ; $A6A3
    ldy     #$1F                    ; $A6A6

@loop:
    sta     a:musicNotesPtr,y       ; $A6A8
    dey                             ; $A6AB
    bpl     @loop                   ; $A6AC
    sta     DMC_RAW                 ; $A6AE
    lda     #$0F                    ; $A6B1
    sta     SND_CHN                 ; $A6B3
    sta     ram_076B                ; $A6B6
    lda     #$00                    ; $A6B9
    sta     PPUMASK                 ; $A6BB
    jsr     Oam_HideAll             ; $A6BE
    jsr     Ppu_ClearNametables     ; $A6C1
    inc     renderingOff            ; $A6C4
    lda     #$06                    ; $A6C7
    sta     ppuMaskExtra            ; $A6C9
    lda     #NMI_MODE_BANK5         ; $A6CC
    sta     nmiMode                 ; $A6CE
    lda     #$B0                    ; $A6D1
    sta     ppuCtrlShadow           ; $A6D3
    sta     PPUCTRL                 ; $A6D5
    rts                             ; $A6D8

; ---------------------------------------------------------------------------
; Bank5_RunState
;
; The bank 5 state machine, run by Bank5_Nmi every frame.  It uses gameState
; for its own states: 0 = title screen and story (Title_Run), 1 = file
; screens (FileScreen_Run), 2 = leave for the game (Bank5_StartGame).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Bank5_RunState:
    jsr     Game_CheckStateChange   ; $A6D9
    jsr     JumpTable               ; $A6DC
; (inline jump table)
    .word   Title_Run               ; $A6DF
    .word   FileScreen_Run          ; $A6E1
    .word   Bank5_StartGame         ; $A6E3

; ---------------------------------------------------------------------------
; Bank5_StartGame
;
; gameState 2: switch the NMI back to the game NMI and set gameState 0, so
; that the next frame starts the game (GameState_Begin).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Bank5_StartGame:
    lda     #NMI_MODE_GAME          ; $A6E5
    sta     nmiMode                 ; $A6E7
    lda     #$00                    ; $A6EA
    sta     gameState               ; $A6EC
    rts                             ; $A6EF

; ---------------------------------------------------------------------------
; Title_Run
;
; gameState 0: the title screen.  In modes 3 and 4 it animates the stars
; first.  Modes: 0 Title_Init, 1 Title_DrawScreen, 2 Title_Show,
; 3 Title_Idle, 4 Story_Run.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_Run:
    lda     gameMode                ; $A6F0
    cmp     #$03                    ; $A6F3
    bcc     @loc_A6FF               ; $A6F5
    jsr     Title_AnimateStars      ; $A6F7
    jsr     Title_AnimateSparkles   ; $A6FA
    lda     #$00                    ; $A6FD

@loc_A6FF:
    jsr     Game_CheckModeChange    ; $A6FF
    jsr     JumpTable               ; $A702
; (inline jump table)
    .word   Title_Init              ; $A705
    .word   Title_DrawScreen        ; $A707
    .word   Title_Show              ; $A709
    .word   Title_Idle              ; $A70B
    .word   Story_Run               ; $A70D

; ---------------------------------------------------------------------------
; Title_Init
;
; Title mode 0: clear the work RAM, set the MMC1 control register
; (horizontal mirroring, 8K CHR), start the title song (soundMute = 1) unless
; flutePlayed (here a "title song started" flag) is set, set up the scroll
; variables (Title_InitScroll), map CHR bank 0, and blank the screen for
; mode 1.  flutePlayed is always 0 here in the movies: power-on,
; Title_CheckStart and Ram_ClearExceptSaved clear it.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_Init:
    jsr     Ram_ClearWork           ; $A70F
    lda     #$0F                    ; $A712
    jsr     Mmc1_SetControl_Bank5   ; $A714
    lda     flutePlayed             ; $A717
    bne     @loc_A723               ; $A71A
    lda     #$01                    ; $A71C
    sta     soundMute               ; $A71E
    inc     flutePlayed             ; $A720

@loc_A723:
    jsr     Title_InitScroll        ; $A723
    lda     #$00                    ; $A726
    jsr     Mmc1_SetChrBank_Bank5   ; $A728
    jmp     Game_BlankAndNextMode   ; $A72B

; ---------------------------------------------------------------------------
; Title_Show
;
; Title mode 2: load the title sprites, set ram_0727, and turn rendering on
; for mode 3.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_Show:
    jsr     Title_LoadSprites       ; $A72E
    inc     ram_0727                ; $A731
    jmp     Game_UnblankAndNextMode ; $A734

; ---------------------------------------------------------------------------
; Title_Idle
;
; Title mode 3: the title screen.  Waits for sprite 0 (the split below the
; logo) and sets the scroll below it from titleSplitAddr, then checks START
; (Title_CheckStart).  The screen first scrolls up, one line every 4 frames
; during part 2 of the title song, until ppuScrollY is $60; then it waits
; there (Story_Delay, drawing the story's first rows) until part 8 of the
; song starts, and goes to mode 4, the story.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_Idle:
    ldy     #$00                    ; $A737

@loop:
    nop                             ; $A739
    dey                             ; $A73A
    bne     @loop                   ; $A73B

@loop2:
    bit     PPUSTATUS               ; $A73D
    bvc     @loop2                  ; $A740
    ldy     #$00                    ; $A742

@loop3:
    dey                             ; $A744
    bne     @loop3                  ; $A745
    ldy     #$4A                    ; $A747

@loop4:
    dey                             ; $A749
    bne     @loop4                  ; $A74A
    lda     ppuCtrlShadow           ; $A74C
    and     #$FC                    ; $A74E
    ora     titleSplitNametable     ; $A750
    sta     ppuCtrlShadow           ; $A752
    sta     PPUCTRL                 ; $A754
    lda     titleSplitAddr          ; $A757
    ldy     titleSplitAddr+1        ; $A759
    sta     PPUADDR                 ; $A75B
    sty     PPUADDR                 ; $A75E
    lda     PPUDATA                 ; $A761
    lda     PPUDATA                 ; $A764
    lda     PPUSTATUS               ; $A767
    lda     ppuScrollY              ; $A76A
    cmp     #$60                    ; $A76C
    bne     @loc_A787               ; $A76E
    lda     #$80                    ; $A770
    sta     titleDelay              ; $A772
    jsr     Title_CheckStart        ; $A775
    lda     titleMusicPart          ; $A778
    cmp     #$08                    ; $A77A
    beq     @loc_A781               ; $A77C
    jmp     Story_Delay             ; $A77E

@loc_A781:
    inc     gameMode                ; $A781
    jmp     Title_CheckStart        ; $A784

@loc_A787:
    lda     titleMusicPart          ; $A787
    cmp     #$02                    ; $A789
    bne     Title_CheckStart        ; $A78B
    lda     frameCounter            ; $A78D
    and     #$03                    ; $A78F
    bne     Title_CheckStart        ; $A791
    inc     ppuScrollY              ; $A793

; ---------------------------------------------------------------------------
; Title_CheckStart
;
; If START was just pressed, leave the title for the file select screen:
; switch the title music player to part $80 (soundMute = $80; the player
; copies it to titleMusicPart), hide the sprites but sprite 0, turn
; rendering off and go to gameState 1.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_CheckStart:
    lda     joypadHeld              ; $A795
    cmp     joypadHeldPrev          ; $A797
    beq     @done                   ; $A79A
    and     #$10                    ; $A79C
    beq     @done                   ; $A79E
    lda     #$00                    ; $A7A0
    sta     ram_0727                ; $A7A2
    sta     sceneStep               ; $A7A5
    jsr     Oam_HideAllButSprite0   ; $A7A8
    lda     #$80                    ; $A7AB
    sta     soundMute               ; $A7AD
    lda     #$00                    ; $A7AF
    sta     ppuNametable            ; $A7B1
    sta     flutePlayed             ; $A7B4
    sta     fileSubStep             ; $A7B7
    inc     renderingOff            ; $A7BA
    inc     gameState               ; $A7BD

@done:
    rts                             ; $A7C0

