; ---------------------------------------------------------------------------
; Title_LoadSprites
;
; Copy TitleSprites (sprite 0, the logo's sword and the stars) into
; oamBuffer.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_LoadSprites:
    ldy     #$FF                    ; $A8C1

@loop:
    lda     TitleSprites,y          ; $A8C3
    sta     oamBuffer,y             ; $A8C6
    dey                             ; $A8C9
    cpy     #$FF                    ; $A8CA
    bne     @loop                   ; $A8CC
    rts                             ; $A8CE

; ---------------------------------------------------------------------------
; Title_AnimateStars
;
; Every 16 frames, cycle the palette of the stars (sprites 26-52, keeping
; their behind-the-background bit).  When frameCounter wraps to 0, start
; the shooting star (sprite 27, until then an ordinary star), which falls
; 2 lines and 3 pixels right every 4 frames until Y $37, then is parked at
; Y $F8.  It stays there until Title_LoadSprites reloads it (at the end of
; the story), so it falls once per title cycle.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_AnimateStars:
    ldx     #$6B                    ; $A8CF
    lda     frameCounter            ; $A8D1
    and     #$0F                    ; $A8D3
    bne     @loc_A8E8               ; $A8D5

@loop:
    inc     oamBuffer+103,x         ; $A8D7
    lda     oamBuffer+103,x         ; $A8DA
    and     #$23                    ; $A8DD
    sta     oamBuffer+103,x         ; $A8DF
    dex                             ; $A8E2
    dex                             ; $A8E3
    dex                             ; $A8E4
    dex                             ; $A8E5
    bpl     @loop                   ; $A8E6

@loc_A8E8:
    lda     frameCounter            ; $A8E8
    bne     @loc_A8EE               ; $A8EA
    inc     titleShootingStar       ; $A8EC

@loc_A8EE:
    lda     oamBuffer+108           ; $A8EE
    cmp     #$37                    ; $A8F1
    bcc     @loc_A8FE               ; $A8F3
    lda     #$00                    ; $A8F5
    sta     titleShootingStar       ; $A8F7
    lda     #$F8                    ; $A8F9
    sta     oamBuffer+108           ; $A8FB

@loc_A8FE:
    lda     titleShootingStar       ; $A8FE
    beq     @done                   ; $A900
    lda     frameCounter            ; $A902
    and     #$03                    ; $A904
    bne     @done                   ; $A906
    inc     oamBuffer+108           ; $A908
    inc     oamBuffer+108           ; $A90B
    inc     oamBuffer+111           ; $A90E
    inc     oamBuffer+111           ; $A911
    inc     oamBuffer+111           ; $A914

@done:
    rts                             ; $A917

; ---------------------------------------------------------------------------
; Title_AnimateSparkles
;
; Every 8 frames, cycle the palette of sprites 53-63 (sparkles below the
; logo) through palettes 0-3.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
