    lda     oamBuffer+211,x         ; $A923
    and     #$03                    ; $A926
    sta     oamBuffer+211,x         ; $A928
    dex                             ; $A92B
    dex                             ; $A92C
    dex                             ; $A92D
    dex                             ; $A92E
    bpl     @loop                   ; $A92F

@done:
    rts                             ; $A931

