    .byte   $4D, $70, $93, $B6, $D9, $FC, $1F, $42, $65, $88, $AB, $CE, $F1, $F1, $F1, $F1; $AB23
    .byte   $4D, $70, $93, $B6, $D9, $FC, $1F, $42, $65, $88, $AB, $CE, $F1, $F1; $AB33

TitleBgRowPtrsHi:
    .byte   $B0, $B0, $B0, $B0, $B0, $B0, $B1, $B1, $B1, $B1, $B1, $B1, $B1, $B1, $B1, $B1; $AB41
    .byte   $B0, $B0, $B0, $B0, $B0, $B0, $B1, $B1, $B1, $B1, $B1, $B1, $B1, $B1; $AB51

TitleLogoPtrs:
    .word   $AF69, $AF84, $AFAA, $AFC6 ; $AB5F
    .word   $AFDB, $AFEF, $B014     ; $AB67

; ---------------------------------------------------------------------------
; Story_Run
;
; Title mode 4: the story scroll.  Sets the scroll below the sprite 0 split
; like Title_Idle and checks START.  After titleDelay (512 frames), it
; scrolls the screen up one line every 4 frames, switching nametables every
; 240 lines, and every 8 lines runs one step of the scene (Story_RunStep),
; one step every 4 frames until the chain returns to step 0: 0
; Story_ClearTextRows, 1 Story_DrawTextLine, 2 Story_DrawTextAttr,
; 3 Title_DrawBgRow, 4 Title_DrawBgAttr, 5 Story_End.  The steps draw the
; story into nametable 2 and redraw the landscape row by row into the other
; nametable, moving the split with it.  Once the background has wrapped
; (titleBgRow 0) and the scroll is at $60 again, step 5 brings the title
; back.  titleScrollHeld runs the steps without scrolling.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_Run:
    ldy     #$00                    ; $AB6D

@loop:
    nop                             ; $AB6F
    dey                             ; $AB70
    bne     @loop                   ; $AB71

@loop2:
    bit     PPUSTATUS               ; $AB73
    bvc     @loop2                  ; $AB76
    ldy     #$00                    ; $AB78

@loop3:
    dey                             ; $AB7A
    bne     @loop3                  ; $AB7B
    ldy     #$4A                    ; $AB7D

@loop4:
    dey                             ; $AB7F
    bne     @loop4                  ; $AB80
    lda     ppuCtrlShadow           ; $AB82
    and     #$FC                    ; $AB84
    ora     titleSplitNametable     ; $AB86
    sta     ppuCtrlShadow           ; $AB88
    sta     PPUCTRL                 ; $AB8A
    lda     titleSplitAddr          ; $AB8D
    ldy     titleSplitAddr+1        ; $AB8F
    sta     PPUADDR                 ; $AB91
    sty     PPUADDR                 ; $AB94
    lda     PPUDATA                 ; $AB97
    lda     PPUDATA                 ; $AB9A
    lda     PPUSTATUS               ; $AB9D
    jsr     Title_CheckStart        ; $ABA0
    lda     renderingOff            ; $ABA3
    bne     Story_Delay_Done        ; $ABA6
    lda     titleDelay              ; $ABA8
    bne     Story_Delay             ; $ABAB
    lda     titleScrollHeld         ; $ABAD
    bne     Story_RunStep           ; $ABAF
    lda     frameCounter            ; $ABB1
    and     #$03                    ; $ABB3
    bne     Story_Delay_Done        ; $ABB5
    inc     ppuScrollY              ; $ABB7
    lda     ppuScrollY              ; $ABB9
    cmp     #$F0                    ; $ABBB
    bne     @loc_ABCB               ; $ABBD
    lda     #$00                    ; $ABBF
    sta     ppuScrollY              ; $ABC1
    lda     ppuNametable            ; $ABC3
    eor     #$02                    ; $ABC6
    sta     ppuNametable            ; $ABC8

@loc_ABCB:
    lda     sceneStep               ; $ABCB
    bne     Story_RunStep           ; $ABCE
    lda     titleBgRow              ; $ABD0
    bne     @loc_ABDF               ; $ABD2
    lda     ppuScrollY              ; $ABD4
    cmp     #$60                    ; $ABD6
    bne     @loc_ABDF               ; $ABD8
    lda     #$05                    ; $ABDA
    sta     sceneStep               ; $ABDC

@loc_ABDF:
    lda     ppuScrollY              ; $ABDF
    and     #$07                    ; $ABE1
    bne     Story_Delay_Done        ; $ABE3

Story_RunStep:
    lda     sceneStep               ; $ABE5
    jsr     JumpTable               ; $ABE8
; (inline jump table)
    .word   Story_ClearTextRows     ; $ABEB
    .word   Story_DrawTextLine      ; $ABED
    .word   Story_DrawTextAttr      ; $ABEF
    .word   Title_DrawBgRow         ; $ABF1
    .word   Title_DrawBgAttr        ; $ABF3
    .word   Story_End               ; $ABF5

; ---------------------------------------------------------------------------
; Story_Delay
;
; While titleDelay runs: count it down (Story_TickDelay) and run the scene
; steps until the first story line is drawn and the chain is back at step
; 0.  From Title_Idle at scroll $60 this draws the first line, its
; attributes and background row 0, one step a frame.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_Delay:
    jsr     Story_TickDelay         ; $ABF7
    lda     titleTextLine           ; $ABFA
    beq     Story_RunStep           ; $ABFC
    lda     sceneStep               ; $ABFE
    beq     Story_Delay_Done        ; $AC01
    jmp     Story_RunStep           ; $AC03

Story_Delay_Done:
    rts                             ; $AC06

; ---------------------------------------------------------------------------
; Story_TickDelay
;
; Count titleDelay down every 4 frames.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_TickDelay:
    lda     frameCounter            ; $AC07
    and     #$03                    ; $AC09
    bne     @done                   ; $AC0B
    dec     titleDelay              ; $AC0D

@done:
    rts                             ; $AC10

StoryBlankRow:
    .byte   $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4; $AC11
    .byte   $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $F4, $FD; $AC21

; ---------------------------------------------------------------------------
; Story_ClearTextRows
;
; Scene step 0: on a 16-line boundary, queue two blank rows at titleTextAddr
; (the two text rows coming into view) and go to step 1; otherwise go to
; step 3, the background.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_ClearTextRows:
    lda     ppuScrollY              ; $AC31
    and     #$0F                    ; $AC33
    beq     @loc_AC3D               ; $AC35
    lda     #$03                    ; $AC37
    sta     sceneStep               ; $AC39
    rts                             ; $AC3C

@loc_AC3D:
    lda     titleTextAddr           ; $AC3D
    sta     ppuBuffer0              ; $AC3F
    lda     titleTextAddr+1         ; $AC42
    sta     ppuBuffer0+1            ; $AC44
    jsr     Story_NextTextRow       ; $AC47
    lda     titleTextAddr           ; $AC4A
    sta     ppuBuffer0+35           ; $AC4C
    lda     titleTextAddr+1         ; $AC4F
    sta     ppuBuffer0+36           ; $AC51
    lda     #$20                    ; $AC54
    sta     ppuBuffer0+2            ; $AC56
    sta     ppuBuffer0+37           ; $AC59
    ldy     #$1F                    ; $AC5C

@loop:
    lda     StoryBlankRow,y         ; $AC5E
    sta     ppuBuffer0+3,y          ; $AC61
    sta     ppuBuffer0+38,y         ; $AC64
    dey                             ; $AC67
    bpl     @loop                   ; $AC68
    lda     #$FF                    ; $AC6A
    sta     ppuBuffer0+70           ; $AC6C
    inc     sceneStep               ; $AC6F
    rts                             ; $AC72

; ---------------------------------------------------------------------------
; Story_DrawTextLine
;
; Scene step 1: queue story line titleTextLine (29 tiles from StoryText) at
; column 3 of the text row, and advance to the next line and step.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_DrawTextLine:
    ldx     titleTextLine           ; $AC73
    lda     StoryTextPtrsLo,x       ; $AC75
    sta     temp0                   ; $AC78
    lda     StoryTextPtrsHi,x       ; $AC7A
    sta     temp1                   ; $AC7D
    ldy     #$1D                    ; $AC7F
    lda     titleTextAddr           ; $AC81
    sta     ppuBuffer0              ; $AC83
    lda     titleTextAddr+1         ; $AC86
    clc                             ; $AC88
    adc     #$03                    ; $AC89
    sta     ppuBuffer0+1            ; $AC8B
    sty     ppuBuffer0+2            ; $AC8E
    lda     #$FF                    ; $AC91
    sta     ppuBuffer0+3,y          ; $AC93
    dey                             ; $AC96

@loop:
    lda     (temp0),y               ; $AC97
    sta     ppuBuffer0+3,y          ; $AC99
    dey                             ; $AC9C
    bpl     @loop                   ; $AC9D
    jsr     Story_NextTextRow       ; $AC9F
    inc     titleTextLine           ; $ACA2
    inc     sceneStep               ; $ACA4
    rts                             ; $ACA7

; ---------------------------------------------------------------------------
; Story_DrawTextAttr
;
; Scene step 2: after every second line, queue a row of story attributes
; (StoryAttrRows; titleAttrRow 6, the copyright line, gets the second
; palette), advancing titleAttrAddr; after the last line, start again at
; line 0.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_DrawTextAttr:
    lda     titleTextLine           ; $ACA8
    and     #$01                    ; $ACAA
    beq     @loc_ACF6               ; $ACAC
    lda     titleTextLine           ; $ACAE
    cmp     #$0F                    ; $ACB0
    bne     @loc_ACB8               ; $ACB2
    lda     #$00                    ; $ACB4
    sta     titleTextLine           ; $ACB6

@loc_ACB8:
    ldx     titleAttrRow            ; $ACB8
    lda     StoryAttrPtrsLo,x       ; $ACBA
    sta     temp2                   ; $ACBD
    lda     StoryAttrPtrsHi,x       ; $ACBF
    sta     temp3                   ; $ACC2
    ldy     #$08                    ; $ACC4
    lda     titleAttrAddr           ; $ACC6
    sta     ppuBuffer0              ; $ACC8
    lda     titleAttrAddr+1         ; $ACCB
    sta     ppuBuffer0+1            ; $ACCD
    sty     ppuBuffer0+2            ; $ACD0
    lda     #$FF                    ; $ACD3
    sta     ppuBuffer0+3,y          ; $ACD5
    dey                             ; $ACD8

@loop:
    lda     (temp2),y               ; $ACD9
    sta     ppuBuffer0+3,y          ; $ACDB
    dey                             ; $ACDE
    bpl     @loop                   ; $ACDF
    lda     titleAttrAddr+1         ; $ACE1
    clc                             ; $ACE3
    adc     #$08                    ; $ACE4
    sta     titleAttrAddr+1         ; $ACE6
    bne     @loc_ACEE               ; $ACE8
    lda     #$C0                    ; $ACEA
    sta     titleAttrAddr+1         ; $ACEC

@loc_ACEE:
    inc     titleAttrRow            ; $ACEE
    lda     titleAttrRow            ; $ACF0
    and     #$07                    ; $ACF2
    sta     titleAttrRow            ; $ACF4

@loc_ACF6:
    inc     sceneStep               ; $ACF6
    rts                             ; $ACF9

; ---------------------------------------------------------------------------
; Title_DrawBgRow
;
; Scene step 3: queue background row titleBgRow (32 tiles taken from
; TitleScreenText) at titleBgAddr and advance it, wrapping to the other
; nametable at its end.  After rows 16 and 30 go to step 4 (attributes);
; otherwise restart at step 0.  Row 30 wraps to row 0.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_DrawBgRow:
    ldx     titleBgRow              ; $ACFA
    lda     TitleBgRowPtrsLo,x      ; $ACFC
    sta     temp0                   ; $ACFF
    lda     TitleBgRowPtrsHi,x      ; $AD01
    sta     temp1                   ; $AD04
    ldy     #$20                    ; $AD06
    lda     titleBgAddr             ; $AD08
    sta     ppuBuffer0              ; $AD0A
    lda     titleBgAddr+1           ; $AD0D
    sta     ppuBuffer0+1            ; $AD0F
    sty     ppuBuffer0+2            ; $AD12
    lda     #$FF                    ; $AD15
    sta     ppuBuffer0+3,y          ; $AD17
    dey                             ; $AD1A

@loop:
    lda     (temp0),y               ; $AD1B
    sta     ppuBuffer0+3,y          ; $AD1D
    dey                             ; $AD20
    bpl     @loop                   ; $AD21
    lda     titleBgAddr+1           ; $AD23
    clc                             ; $AD25
    adc     #$20                    ; $AD26
    sta     titleBgAddr+1           ; $AD28
    lda     titleBgAddr             ; $AD2A
    adc     #$00                    ; $AD2C
    sta     titleBgAddr             ; $AD2E
    inc     titleBgRow              ; $AD30
    lda     titleBgRow              ; $AD32
    cmp     #$10                    ; $AD34
    beq     @loc_AD40               ; $AD36
    cmp     #$1E                    ; $AD38
    bne     Story_RestartSteps      ; $AD3A
    lda     #$00                    ; $AD3C
    sta     titleBgRow              ; $AD3E

@loc_AD40:
    lda     titleBgAddr+1           ; $AD40
    cmp     #$C0                    ; $AD42
    bne     @loc_AD5A               ; $AD44
    lda     titleBgAddr             ; $AD46
    and     #$23                    ; $AD48
    cmp     #$23                    ; $AD4A
    bne     @loc_AD5A               ; $AD4C
    lda     #$00                    ; $AD4E
    sta     titleBgAddr+1           ; $AD50
    lda     titleBgAddr             ; $AD52
    and     #$28                    ; $AD54
    eor     #$08                    ; $AD56
    sta     titleBgAddr             ; $AD58

@loc_AD5A:
    inc     sceneStep               ; $AD5A
    rts                             ; $AD5D

; ---------------------------------------------------------------------------
; Story_RestartSteps
;
; Set sceneStep 0.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_RestartSteps:
    lda     #$00                    ; $AD5E
    sta     sceneStep               ; $AD60
    rts                             ; $AD63

TitleBgAttrBlank:
    .byte   $00, $00, $00, $00, $00, $00, $00, $CC                          ; $AD64
    .byte   $00, $00, $00, $00, $00, $00, $00, $CC                          ; $AD6C
    .byte   $00, $00, $00, $00, $00, $00, $00, $CC                          ; $AD74

; ---------------------------------------------------------------------------
; Title_DrawBgAttr
;
; Scene step 4: queue 24 bytes of background attributes (from the title's
; attribute string) at titleBgAttrAddr and blank ones in the other half,
; advance titleBgAttrAddr, and move the sprite 0 split address down by 16
; rows (switching nametables when it wraps: $2A00, $2000, $2200, ...).
; Then restart at step 0.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_DrawBgAttr:
    lda     #$14                    ; $AD7C
    sta     temp2                   ; $AD7E
    lda     #$B2                    ; $AD80
    sta     temp3                   ; $AD82
    ldy     #$18                    ; $AD84
    lda     titleBgAttrAddr         ; $AD86
    sta     ppuBuffer0              ; $AD88
    sta     ppuBuffer0+27           ; $AD8B
    lda     titleBgAttrAddr+1       ; $AD8E
    sta     ppuBuffer0+1            ; $AD90
    eor     #$20                    ; $AD93
    sta     ppuBuffer0+28           ; $AD95
    sty     ppuBuffer0+2            ; $AD98
    sty     ppuBuffer0+29           ; $AD9B
    lda     #$FF                    ; $AD9E
    sta     ppuBuffer0+30,y         ; $ADA0
    dey                             ; $ADA3

@loop:
    lda     (temp2),y               ; $ADA4
    sta     ppuBuffer0+3,y          ; $ADA6
    lda     TitleBgAttrBlank,y      ; $ADA9
    sta     ppuBuffer0+30,y         ; $ADAC
    dey                             ; $ADAF
    bpl     @loop                   ; $ADB0
    lda     titleBgAttrAddr+1       ; $ADB2
    clc                             ; $ADB4
    adc     #$20                    ; $ADB5
    sta     titleBgAttrAddr+1       ; $ADB7
    bne     @loc_ADC5               ; $ADB9
    lda     titleBgAttrAddr         ; $ADBB
    eor     #$08                    ; $ADBD
    sta     titleBgAttrAddr         ; $ADBF
    lda     #$C0                    ; $ADC1
    sta     titleBgAttrAddr+1       ; $ADC3

@loc_ADC5:
    inc     titleSplitAddr          ; $ADC5
    inc     titleSplitAddr          ; $ADC7
    lda     titleSplitAddr          ; $ADC9
    and     #$04                    ; $ADCB
    beq     @loc_ADDD               ; $ADCD
    lda     titleSplitNametable     ; $ADCF
    eor     #$02                    ; $ADD1
    sta     titleSplitNametable     ; $ADD3
    lda     titleSplitAddr          ; $ADD5
    and     #$28                    ; $ADD7
    eor     #$08                    ; $ADD9
    sta     titleSplitAddr          ; $ADDB

@loc_ADDD:
    jmp     Story_RestartSteps      ; $ADDD

; ---------------------------------------------------------------------------
; Title_InitScroll
;
; Set up the title scroll: the nametable addresses of the next background
; row ($2000), story text row ($2800), story attributes ($2BC0) and
; background attributes ($23C0); the split address ($2A00, nametable 2);
; and zero the row counters, sceneStep and the scroll.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Title_InitScroll:
    lda     #$2A                    ; $ADE0
    sta     titleSplitAddr          ; $ADE2
    lda     #$20                    ; $ADE4
    sta     titleBgAddr             ; $ADE6
    lda     #$28                    ; $ADE8
    sta     titleTextAddr           ; $ADEA
    lda     #$2B                    ; $ADEC
    sta     titleAttrAddr           ; $ADEE
    lda     #$23                    ; $ADF0
    sta     titleBgAttrAddr         ; $ADF2
    lda     #$00                    ; $ADF4
    sta     titleSplitAddr+1        ; $ADF6
    sta     titleBgAddr+1           ; $ADF8
    sta     titleTextAddr+1         ; $ADFA
    sta     titleBgRow              ; $ADFC
    sta     titleAttrRow            ; $ADFE
    sta     titleTextLine           ; $AE00
    sta     sceneStep               ; $AE02
    sta     ppuNametable            ; $AE05
    sta     ppuScrollY              ; $AE08
    lda     #$C0                    ; $AE0A
    sta     titleAttrAddr+1         ; $AE0C
    sta     titleBgAttrAddr+1       ; $AE0E
    lda     #$02                    ; $AE10
    sta     titleSplitNametable     ; $AE12

Title_InitScroll_Done:
    rts                             ; $AE14

; ---------------------------------------------------------------------------
; Story_End
;
; Scene step 5: after the story text, scroll the title screen back into
; view, redrawing its rows (titleEndStep: 0 Story_RedrawLogoRow,
; 1 Story_EndDrawBgRow, 2 Story_EndDrawBgAttr).  When the background is
; complete, reload the sprites and return to Title_Idle (mode 3).  The
; branch for a running titleDelay is never taken: only
; Story_RedrawLogoRow's unreachable wrap sets it.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_End:
    lda     ppuNametable            ; $AE15
    bne     @loc_AE4A               ; $AE18
    lda     titleDelay              ; $AE1A
    beq     @loc_AE30               ; $AE1D
; (code below not executed in the test movies)
    jsr     Story_TickDelay         ; $AE1F
    lda     #$01                    ; $AE22
    sta     titleScrollHeld         ; $AE24
    lda     titleMusicPart          ; $AE26
    cmp     #$02                    ; $AE28
    bne     @done                   ; $AE2A
    lda     #$00                    ; $AE2C
    sta     titleScrollHeld         ; $AE2E
; (end of code not executed in the test movies)

@loc_AE30:
    lda     titleBgRow              ; $AE30
    bne     @loc_AE4A               ; $AE32
    lda     titleEndStep            ; $AE34
    bne     @loc_AE4A               ; $AE36
    lda     #$00                    ; $AE38
    sta     sceneStep               ; $AE3A
    sta     titleEndStep            ; $AE3D
    sta     titleLogoString         ; $AE3F
    jsr     Title_LoadSprites       ; $AE41
    lda     #$03                    ; $AE44
    sta     gameMode                ; $AE46

@done:
    rts                             ; $AE49

@loc_AE4A:
    lda     titleEndStep            ; $AE4A
    jsr     JumpTable               ; $AE4C
; (inline jump table)
    .word   Story_RedrawLogoRow     ; $AE4F
    .word   Story_EndDrawBgRow      ; $AE51
    .word   Story_EndDrawBgAttr     ; $AE53

; ---------------------------------------------------------------------------
; Story_RedrawLogoRow
;
; Every 8 lines, blank the text row coming into view and, when the next logo
; string (titleLogoString) starts on that row, queue it as well
; (Story_CopyLogoString), until all 7 are drawn.  Its wrap at scroll $F0
; never runs: Story_Run wraps the scroll first.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_RedrawLogoRow:
    lda     ppuScrollY              ; $AE55
    and     #$07                    ; $AE57
    bne     Title_InitScroll_Done   ; $AE59
    lda     ppuScrollY              ; $AE5B
    cmp     #$F0                    ; $AE5D
    bne     @loc_AE72               ; $AE5F
; (code below not executed in the test movies)
    lda     #$00                    ; $AE61
    sta     ppuScrollY              ; $AE63
    lda     ppuNametable            ; $AE65
    eor     #$02                    ; $AE68
    sta     ppuNametable            ; $AE6A
    lda     #$90                    ; $AE6D
    sta     titleDelay              ; $AE6F
; (end of code not executed in the test movies)

@loc_AE72:
    lda     titleLogoString         ; $AE72
    asl     a                       ; $AE74
    tax                             ; $AE75
    lda     TitleLogoPtrs,x         ; $AE76
    sta     temp0                   ; $AE79
    lda     TitleLogoPtrs+1,x       ; $AE7B
    sta     temp1                   ; $AE7E
    lda     titleTextAddr           ; $AE80
    sta     ppuBuffer0              ; $AE82
    lda     titleTextAddr+1         ; $AE85
    sta     ppuBuffer0+1            ; $AE87
    lda     #$20                    ; $AE8A
    sta     ppuBuffer0+2            ; $AE8C
    lda     #$FF                    ; $AE8F
    ldy     #$1F                    ; $AE91
    sta     ppuBuffer0+4,y          ; $AE93

@loop:
    lda     StoryBlankRow,y         ; $AE96
    sta     ppuBuffer0+3,y          ; $AE99
    dey                             ; $AE9C
    bpl     @loop                   ; $AE9D
    lda     titleLogoString         ; $AE9F
    cmp     #$07                    ; $AEA1
    beq     @loc_AEBB               ; $AEA3
    ldy     #$00                    ; $AEA5
    lda     (temp0),y               ; $AEA7
    cmp     titleTextAddr           ; $AEA9
    bne     @loc_AEBB               ; $AEAB
    iny                             ; $AEAD
    lda     (temp0),y               ; $AEAE
    and     #$F0                    ; $AEB0
    cmp     titleTextAddr+1         ; $AEB2
    bne     @loc_AEBB               ; $AEB4
