; ---------------------------------------------------------------------------
; Story_NextTextRow
;
; Advance titleTextAddr by one row (32 bytes), wrapping from the end of a
; nametable to the top of the other one.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Story_NextTextRow:
    lda     titleTextAddr+1         ; $AEC1
