    adc     #$20                    ; $AEC4
    sta     titleTextAddr+1         ; $AEC6
    lda     titleTextAddr           ; $AEC8
    adc     #$00                    ; $AECA
    sta     titleTextAddr           ; $AECC
    and     #$03                    ; $AECE
    cmp     #$03                    ; $AED0
    bne     @done                   ; $AED2
    lda     titleTextAddr+1         ; $AED4
