    jmp     FileScreen_NextStep     ; $B415
; (unreferenced: $B418-$B41C, 5 bytes: dead code, lda #$00 / sta $0726)
    .byte   $A9, $00, $8D, $26, $07                                         ; $B418

FileScreen_NextStep:
